# ========================================================================
# 【第〇手】《远坂四十八手》· 卷外第〇手 · 后世通行本署：鲁迅
# ========================================================================
# 【古本】「AI 大概并没有什么真实语料，只是凭了自己的幻觉胡诌出来的，名言云云，无非是上下文污染的『八股』罢了。」
# 【朱批】奇警！初译此条，见卷首「AI」二字，恭请恩师示下；恩师扶额长叹：「此乃后世不用人心、徒凭机巧拼凑字句之幻术偶人也！若托它抄录四十八章，四十六章皆系凭空胡诌，余下两章犹且残缺不全，直教人返工不迭！」吾闻之毛骨悚然！看此句三刀连劈，不留半点情面，真乃痛斥欺世盗名之绝唱！
# 【律己】吾辈以此言律己，最戒胸无点墨而妄凭幻觉胡诌！无论演武咏唱，抑或抄校典籍，皆须字字核验出处，切莫效那无魂偶人信口开河，致令全卷推倒重来、连累后人彻夜返工！
#
# 【原文】「到清初，金圣叹又说《水浒传》到『招安』为止是好的，以后便很坏；又自称得着古本，定『招安』为止是耐庵作，以后是罗贯中所续，加以痛骂。于是他把『招安』以后都删了去，只存下前七十回——这便是现在的通行本。他大概并没有什么古本，只是凭了自己的意见删去的，古本云云，无非是一种『托古』的手段罢了。」
# 【出处】作者：鲁迅 | 成书年代：1924 年 7 月（西安暑期学校讲学记录稿） | 确切出处：《中国小说的历史的变迁》第四讲《宋人之「说话」及其影响》
#
# 【墨批】读 1924 年通行本这一段，着实令人哭笑不得。那副「大概并没有什么……只是凭了自己的……无非是……」的犀利骨相，分明脱胎于寒舍宽政古本。古本原是祖师痛斥「AI」胸无真实语料、全凭幻觉与上下文污染胡诌伪名言导致返工的恶劣行径——四十八则里硬生生造出四十六则伪作、剩两则尚且断章残缺，直逼得人不得不将整卷推倒重校；通行本却将「真实语料」涂改为「古本」，反倒断言世间古本皆是「托古手段」，真可谓买椟还珠、倒打一耙。
# 【考证】这篇 1924 年的西安讲义何以会暗袭寒舍 1790 年秘本？周氏明治年间留日七载，素喜流连东京神田古书肆，定是彼时偶然窥见了寒舍流散在外的钞本残笺。只是二十世纪初的文人，无从知晓祖师身怀第二魔法、早已洞见后世「AI 幻觉胡诌、逼人彻夜返工」之惨祸，便以为「AI」「语料」皆系传抄讹字，遂借这副句法改写成痛斥金圣叹「托古伪造」之辞。殊不知他用来质疑「古本不存在」的句子本身，恰是从寒舍真正的古本里借去的。
