COUNTDOWN_QUOTES: Tuple[dict, ...] = tuple(
    {
        "id": h["id"],
        "category": "aphorism",
        "handIndex": h["handIndex"],
        "handLabel": h["handLabel"],
        "author": h["surfaceAuthor"],
        "origin": f"《远坂四十八手》· {h['handLabel']}",
        "text": h["ancientText"],
    }
    for h in ANCIENT_CODEX_HANDS
) + STUDY_NOTES

_last_target: Optional[datetime] = None
_quote_cursor: int = 0
_quote_deck: List[dict] = []
_quote_deck_cycle: int = 0


def _ensure_valid_datetime(reference: Optional[datetime] = None) -> datetime:
    if isinstance(reference, datetime):
        return reference
    return datetime.now()


_UTF8_STDIO_CONFIGURED: bool = False


def _ensure_utf8_stdio() -> None:
    global _UTF8_STDIO_CONFIGURED
    if _UTF8_STDIO_CONFIGURED:
        return
    _UTF8_STDIO_CONFIGURED = True
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            try:
                stream.reconfigure(encoding="utf-8", errors="replace")
            except Exception:
                pass
    if sys.platform == "win32" and hasattr(sys.stdout, "isatty") and sys.stdout.isatty():
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32
            for std_handle_id in (-11, -12):
                handle = kernel32.GetStdHandle(std_handle_id)
                if handle and handle != -1:
                    mode = ctypes.c_uint32()
                    if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                        kernel32.SetConsoleMode(handle, mode.value | 0x0004)
        except Exception:
            pass


def _safe_write(text: str) -> None:
    _ensure_utf8_stdio()
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except UnicodeEncodeError:
        try:
            enc = getattr(sys.stdout, "encoding", None) or "utf-8"
            sys.stdout.write(text.encode(enc, errors="replace").decode(enc, errors="replace"))
            sys.stdout.flush()
        except Exception:
            pass
    except Exception:
        pass


CODEX_TOTAL_PAGES: int = 3 + len(ANCIENT_CODEX_HANDS) * 2
CODEX_BOX_INNER_WIDTH: int = 76
CODEX_DEFAULT_WRAP_WIDTH: int = 86


def clear_terminal_screen() -> None:
    _ensure_utf8_stdio()
    try:
        if hasattr(sys.stdout, "isatty") and sys.stdout.isatty():
            sys.stdout.write("\x1b[H\x1b[J")
            sys.stdout.flush()
    except Exception:
        pass


def format_remaining_duration(remaining_seconds: float) -> str:
    total = max(0, int(remaining_seconds))
    if total >= 3600:
        hrs = total // 3600
        mins = (total % 3600) // 60
        secs = total % 60
        return f"{hrs}h {mins:02d}m {secs:02d}s"
    return f"{total // 60}m {total % 60}s"


def get_char_display_width(ch: str) -> int:
    if not ch:
        return 0
    c = ch[0]
    code = ord(c)
    if code <= 0x007F:
        return 1
    if 0x2500 <= code <= 0x259F:
        return 1
    if unicodedata.combining(c):
        return 0
    return 2 if unicodedata.east_asian_width(c) in ("W", "F") else 1


def get_display_width(text: str) -> int:
    return sum(get_char_display_width(ch) for ch in str(text or ""))


def truncate_display_width(text: str, max_width: int) -> str:
    s = str(text or "")
    if max_width <= 0:
        return ""
    if get_display_width(s) <= max_width:
        return s
    out: List[str] = []
    cur_w = 0
    for ch in s:
        cw = get_char_display_width(ch)
        if cur_w + cw > max_width:
            break
        out.append(ch)
        cur_w += cw
    return "".join(out)


def pad_display_width(text: str, target_width: int) -> str:
    s = str(text or "")
    w = get_display_width(s)
    if w >= target_width:
        return s
    return s + (" " * (target_width - w))


def get_terminal_viewport_size() -> Tuple[int, int, int, int]:
    try:
        term_size = shutil.get_terminal_size((96, 25))
        cols = term_size.columns if term_size.columns > 40 else 96
        rows = term_size.lines if term_size.lines > 12 else 25
    except Exception:
        cols, rows = 96, 25
    box_inner_width = min(108, max(74, cols - 6))
    max_body_rows = max(11, rows - 8)
    return cols, rows, box_inner_width, max_body_rows


def make_double_box_header(
    left_title: str,
    right_badge: str = "",
    inner_width: int = CODEX_BOX_INNER_WIDTH,
) -> List[str]:
    top = "╔" + ("═" * inner_width) + "╗"
    bottom = "╚" + ("═" * inner_width) + "╝"
    left_str = " " + str(left_title or "")
    right_str = (str(right_badge) + " ") if right_badge else ""
    right_w = get_display_width(right_str)
    if right_w >= inner_width:
        combined = truncate_display_width(right_str, inner_width)
    else:
        max_left_w = max(0, inner_width - right_w - (1 if right_str else 0))
        if get_display_width(left_str) > max_left_w:
            left_str = truncate_display_width(left_str, max_left_w)
            if "〔" in left_str and "〕" not in left_str and max_left_w >= 2:
                left_str = truncate_display_width(left_str, max_left_w - 2) + "〕"
        gap = max(1 if right_str else 0, inner_width - get_display_width(left_str) - right_w)
        combined = truncate_display_width(left_str + (" " * gap) + right_str, inner_width)
    middle = "║" + pad_display_width(combined, inner_width) + "║"
    return [top, middle, bottom]


def make_single_box_bar(
    text: str,
    inner_width: int = CODEX_BOX_INNER_WIDTH,
) -> List[str]:
    top = "┌" + ("─" * inner_width) + "┐"
    bottom = "└" + ("─" * inner_width) + "┘"
    raw_content = " " + str(text or "")
    if get_display_width(raw_content) > inner_width:
        raw_content = truncate_display_width(raw_content, max(0, inner_width - 1))
    middle = "│" + pad_display_width(raw_content, inner_width) + "│"
    return [top, middle, bottom]


def wrap_display_paragraph(
    text: str,
    max_cols: int = CODEX_DEFAULT_WRAP_WIDTH,
    first_indent: str = "  ",
    next_indent: str = "  ",
) -> List[str]:
    clean = re.sub(r"\s+", " ", str(text or "")).strip()
    if not clean:
        return []
    lines: List[str] = []
    current = first_indent
    current_w = get_display_width(first_indent)
    next_indent_w = get_display_width(next_indent)

    for ch in clean:
        cw = get_char_display_width(ch)
        if current_w + cw > max_cols:
            lines.append(current)
            current = next_indent + ch
            current_w = next_indent_w + cw
        else:
            current += ch
            current_w += cw
    if current.strip():
        lines.append(current)
    return lines


def get_countdown_quotes(category: str = "all") -> List[dict]:
    if category in ("aphorism", "complaint"):
        return [item for item in COUNTDOWN_QUOTES if item.get("category") == category]
    return list(COUNTDOWN_QUOTES)


def get_ancient_codex_frontispiece() -> dict:
    return dict(ANCIENT_CODEX_FRONTISPIECE)


def get_ancient_codex_hands() -> List[dict]:
    return list(ANCIENT_CODEX_HANDS)


def get_codex_total_pages() -> int:
    return CODEX_TOTAL_PAGES


def build_shuffled_quote_deck() -> List[dict]:
    aphorisms = [item for item in COUNTDOWN_QUOTES if item.get("category") != "complaint"]
    complaints = [item for item in COUNTDOWN_QUOTES if item.get("category") == "complaint"]
    random.shuffle(aphorisms)
    deck: List[dict] = []
    a_idx = 0
    c_idx = 0
    while a_idx < len(aphorisms) or c_idx < len(complaints):
        for _ in range(2):
            if a_idx < len(aphorisms):
                deck.append(aphorisms[a_idx])
                a_idx += 1
        if c_idx < len(complaints):
            deck.append(complaints[c_idx])
            c_idx += 1
    return deck


def pick_random_aphorism() -> dict:
    aphorisms = [item for item in COUNTDOWN_QUOTES if item.get("category") != "complaint"]
    if not aphorisms:
        return dict(COUNTDOWN_QUOTES[0])
    return random.choice(aphorisms)


class CountdownTimelineDirector:
    """Directs infinite shuffled aphorisms alongside 25 strictly chronological, non-repeating study notes."""

    def __init__(self, total_wait_seconds: float = 0.0, flip_interval_seconds: float = 7.0) -> None:
        self.total_wait = max(0.0, float(total_wait_seconds))
        self.flip_interval = max(1.0, float(flip_interval_seconds))
        self.essays: List[dict] = [item for item in COUNTDOWN_QUOTES if item.get("category") == "complaint"]
        self.aphorisms: List[dict] = [item for item in COUNTDOWN_QUOTES if item.get("category") != "complaint"]
        self._aphorism_bag: List[dict] = []
        self._last_aphorism_id: Optional[str] = None
        self.next_essay_idx: int = 0
        self.aphorisms_since_essay: int = 0
        self.frame_count: int = 0
        self.finale_locked: bool = False
        self._started_mono: float = time.monotonic()
        self.est_flips: int = max(1, int(self.total_wait // self.flip_interval))
        self.is_long_timer: bool = self.est_flips >= len(self.essays) * 4

    def _draw_aphorism(self) -> dict:
        if not self._aphorism_bag:
            fresh = list(self.aphorisms)
            random.shuffle(fresh)
            if len(fresh) > 1 and self._last_aphorism_id and fresh[0].get("id") == self._last_aphorism_id:
                fresh[0], fresh[-1] = fresh[-1], fresh[0]
            self._aphorism_bag = fresh
        picked = self._aphorism_bag.pop(0)
        self._last_aphorism_id = picked.get("id")
        return picked

    def next_frame(self, elapsed_seconds: Optional[float] = None) -> Tuple[dict, Optional[Tuple[int, int]]]:
        if elapsed_seconds is None:
            elapsed = max(0.0, time.monotonic() - self._started_mono)
        else:
            elapsed = max(0.0, float(elapsed_seconds))
        total_essays = len(self.essays)
        progress = 1.0 if self.total_wait <= 0 else min(1.0, max(0.0, elapsed / self.total_wait))
        remaining = max(0.0, self.total_wait - elapsed)

        if self.finale_locked and total_essays > 0:
            self.frame_count += 1
            return self.essays[-1], (total_essays, total_essays)

        selected_essay_idx: Optional[int] = None
        if self.next_essay_idx < total_essays:
            milestone = (self.next_essay_idx + 1) / (total_essays + 1)
            finale_window = max(15.0, self.flip_interval * 2.0)
            if remaining <= finale_window:
                selected_essay_idx = total_essays - 1
                self.finale_locked = True
            elif self.is_long_timer and self.next_essay_idx < total_essays - 1:
                if progress >= milestone and self.aphorisms_since_essay >= 2:
                    selected_essay_idx = self.next_essay_idx
            elif (
                self.aphorisms_since_essay >= 1
                and self.next_essay_idx < total_essays - 1
                and progress >= milestone
                and remaining > finale_window
            ):
                if self.next_essay_idx == 0:
                    selected_essay_idx = 0
                else:
                    selected_essay_idx = max(
                        self.next_essay_idx,
                        min(total_essays - 2, int(progress * total_essays)),
                    )

        self.frame_count += 1
        if selected_essay_idx is not None:
            essay = self.essays[selected_essay_idx]
            essay_progress = (selected_essay_idx + 1, total_essays)
            self.next_essay_idx = selected_essay_idx + 1
            self.aphorisms_since_essay = 0
            return essay, essay_progress

        aphorism = self._draw_aphorism()
        self.aphorisms_since_essay += 1
        return aphorism, None


def pick_countdown_quote(step_index: Optional[int] = None) -> dict:
    global _quote_cursor, _quote_deck, _quote_deck_cycle
    if not _quote_deck:
        _quote_deck = build_shuffled_quote_deck()
        _quote_deck_cycle = 0
    total = len(_quote_deck)
    if isinstance(step_index, int) and not isinstance(step_index, bool) and step_index >= 0:
        cycle = step_index // total
        if cycle != _quote_deck_cycle:
            _quote_deck = build_shuffled_quote_deck()
            _quote_deck_cycle = cycle
        return _quote_deck[step_index % total]
    picked = _quote_deck[_quote_cursor % total]
    _quote_cursor = (_quote_cursor + 1) % total
    if _quote_cursor == 0:
        _quote_deck = build_shuffled_quote_deck()
        _quote_deck_cycle += 1
    return picked


def format_countdown_quote_line(quote_obj: Optional[dict] = None, index_number: Optional[int] = None) -> str:
    q = quote_obj if isinstance(quote_obj, dict) else pick_random_aphorism()
    prefix_num = f"#{index_number + 1:02d} " if isinstance(index_number, int) and not isinstance(index_number, bool) and index_number >= 0 else ""
    if q.get("category") == "complaint":
        title = str(q.get("author", "")).removeprefix("书房随笔 · ")
        return f"  [书房随笔 {prefix_num}· {title} · {q.get('origin', '')}]\n  「{q.get('text', '')}」"
    return f"  [远坂流古本 {prefix_num}· {q.get('author', '')}]\n  ❝ {q.get('text', '')} ❞"


def get_quote_display_duration(quote_obj: Optional[dict] = None) -> float:
    if not isinstance(quote_obj, dict):
        return 7.0
    if quote_obj.get("category") == "complaint" or len(str(quote_obj.get("text", ""))) > 120:
        return 11.0
    return 7.0


def format_countdown_folio_page(
    task_label: str = "书房要务",
    target_formatted: str = "02:00:00",
    trigger_formatted: str = "01:00:00",
    tohsaka_formatted: str = "01:00:00",
    physical_formatted: str = "00:00:00",
    quote_step: int = 0,
    quote_obj: Optional[dict] = None,
    essay_progress: Optional[Tuple[int, int]] = None,
) -> str:
    step = max(0, int(quote_step))
    page_no = step + 1
    active_quote = quote_obj if isinstance(quote_obj, dict) else pick_countdown_quote(step)
    _, _, box_inner_width, _ = get_terminal_viewport_size()
    if active_quote.get("category") == "complaint":
        if essay_progress and len(essay_progress) == 2:
            essay_no, total_essays = int(essay_progress[0]), int(essay_progress[1])
        else:
            all_essays = get_countdown_quotes("complaint")
            total_essays = max(1, len(all_essays))
            found_idx = next(
                (idx for idx, item in enumerate(all_essays) if item.get("id") == active_quote.get("id")),
                0,
            )
            essay_no = found_idx + 1
        right_badge = f"[旧札 {essay_no:02d} / {total_essays} 篇]"
        title = str(active_quote.get("author", "")).removeprefix("书房随笔 · ")
        kind_tag = f"[书房随笔 · 旧札 {essay_no:02d}/{total_essays} | {title} | {active_quote.get('origin', '')}]"
    else:
        right_badge = f"[展卷第 {page_no:02d} 帧]"
        hand_label = str(active_quote.get("handLabel", "")).strip()
        if hand_label:
            kind_tag = f"[远坂流古本 #{page_no:02d} · {hand_label} | {active_quote.get('author', '')}]"
        else:
            kind_tag = f"[远坂流古本 #{page_no:02d} | {active_quote.get('author', '')}]"

    lines: List[str] = [
        *make_double_box_header(
            "〔Tohsaka | 书房时计候场仪轨〕",
            right_badge,
            box_inner_width,
        ),
        f"  当前读数 : {tohsaka_formatted} | 物理时间 {physical_formatted} | 恒定超前 60 分钟",
        f"  候场事务 : {task_label}",
        f"  约定时刻 : {target_formatted}   -->   提前一小时响铃 : {trigger_formatted}",
        "  " + ("─" * max(40, box_inner_width - 2)),
        *wrap_display_paragraph(kind_tag, box_inner_width, "  ", "  "),
        "",
        *wrap_display_paragraph(f"「{active_quote.get('text', '')}」", box_inner_width, "  ", "  "),
        "",
        *make_single_box_bar(
            "[候场操作] L/空格 锁定驻留 | C 展阅批注 | ←/→/N/P 换帧 | Ctrl+C 退出",
            box_inner_width,
        ),
    ]
    return "\n".join(lines)


def format_countdown_status_line(
    gear_icon: str,
    tohsaka_time_str: str,
    physical_time_str: str,
    rem_str: str,
    frame_duration: Union[int, float] = 7,
    is_locked: bool = False,
    inline_codex_active: bool = False,
    finale_forced: bool = False,
    cols: Optional[int] = None,
    use_color: bool = False,
) -> str:
    term_cols = cols if isinstance(cols, int) and cols > 0 else get_terminal_viewport_size()[0]
    max_width = max(20, term_cols - 2)
    if finale_forced:
        full_tail = "终章锁定 · 静候钟鸣 · Ctrl+C 退出"
        compact_tail = "终章锁定 Ctrl+C退出"
    elif inline_codex_active:
        full_tail = "内联阅卷中 · 按 C/B/Esc 返回候场 · Ctrl+C 退出"
        compact_tail = "C/B返回 Ctrl+C退出"
    elif is_locked:
        full_tail = "已锁定驻留 · 按 L/空格 恢复轮播 · Ctrl+C 退出"
        compact_tail = "已锁定 L恢复 Ctrl+C退出"
    else:
        full_tail = f"每 {int(frame_duration)} 秒自动翻页 · 按 L 锁定 / C 阅卷 · Ctrl+C 退出"
        compact_tail = "L锁定 C阅卷 Ctrl+C退出"

    candidates = (
        f"  {gear_icon} [Tohsaka {tohsaka_time_str} | 物理 {physical_time_str}] 距响铃还剩 {rem_str} · {full_tail}...",
        f"  {gear_icon} [Tohsaka {tohsaka_time_str} | 物理 {physical_time_str}] 距响铃还剩 {rem_str} · {compact_tail}",
        f"  {gear_icon} [Tohsaka {tohsaka_time_str}|物理 {physical_time_str}] 还剩 {rem_str} · {compact_tail}",
        f" {gear_icon} [Tohsaka {tohsaka_time_str}] 剩 {rem_str} · {compact_tail}",
    )
    chosen = candidates[-1]
    for cand in candidates:
        if get_display_width(cand) <= max_width:
            chosen = cand
            break
    plain_line = truncate_display_width(chosen, max_width)
    if use_color:
        tohsaka_plain = f"Tohsaka {tohsaka_time_str}"
        if tohsaka_plain in plain_line:
            plain_line = plain_line.replace(tohsaka_plain, f"\x1b[1;33m{tohsaka_plain}\x1b[0m", 1)
        if rem_str in plain_line:
            plain_line = plain_line.replace(rem_str, f"\x1b[1;33m{rem_str}\x1b[0m", 1)
    return f"\r{plain_line}\x1b[K"


