def has_mystery_violation(text: str) -> bool:
    s = str(text or "")
    return any(r["term"] in s for r in MYSTERY_SUGGESTION_RULES)


def apply_mystery_suggestion(text: str, stage: str = "safe") -> str:
    s = str(text or "")
    if stage == "raw":
        return s
    out = s
    for r in MYSTERY_SUGGESTION_RULES:
        term = r["term"]
        if term not in out:
            continue
        replacement = r["glitch"] if stage == "glitch" else r["safe"]
        out = out.replace(term, replacement)
    return out


def colorize_mystery_glitch_text(formatted_text: str, use_ansi_color: bool = False) -> str:
    s = str(formatted_text or "")
    if not use_ansi_color:
        return s
    styled = stylize_study_terminal(s, enable_color=True)
    ansi_re = re.compile(r"\x1b\[[0-9;]*m")
    token_re = re.compile(r"\x1b\[[0-9;]*m|[▓▒▉▊▋]+")
    out_lines: List[str] = []
    for line in styled.split("\n"):
        plain = ansi_re.sub("", line)
        trimmed = plain.strip()
        if trimmed and trimmed[0] in ("╔", "║", "╚", "┌", "│", "└"):
            out_lines.append(f"\x1b[31;1m{plain}\x1b[0m")
        else:
            active_color = ""

            def _repl(m: re.Match) -> str:
                nonlocal active_color
                tok = m.group(0)
                if tok.startswith("\x1b["):
                    active_color = "" if tok == "\x1b[0m" else tok
                    return tok
                return f"\x1b[31;1m{tok}\x1b[0m{active_color}"

            out_lines.append(token_re.sub(_repl, line))
    return "\n".join(out_lines)


def _should_enable_study_color(enable_color: Optional[bool] = None) -> bool:
    if enable_color is not None:
        return bool(enable_color)
    if os.environ.get("NO_COLOR"):
        return False
    return bool(hasattr(sys.stdout, "isatty") and sys.stdout.isatty())


def _colorize_inline_notes_in_line(line: str, color: str, in_note: bool) -> Tuple[str, bool]:
    out_parts: List[str] = []
    rest = line
    if in_note:
        indent_m = re.match(r"^(\s*)", rest)
        indent = indent_m.group(1) if indent_m else ""
        content = rest[len(indent) :]
        close_idx = content.find("】")
        if close_idx == -1:
            if content:
                return f"{indent}{color}{content}\x1b[0m", True
            return line, True
        out_parts.append(f"{indent}{color}{content[: close_idx + 1]}\x1b[0m")
        rest = content[close_idx + 1 :]
        in_note = False

    while "【夹批：" in rest:
        start_idx = rest.find("【夹批：")
        out_parts.append(rest[:start_idx])
        after = rest[start_idx:]
        close_idx = after.find("】")
        if close_idx != -1:
            out_parts.append(f"{color}{after[: close_idx + 1]}\x1b[0m")
            rest = after[close_idx + 1 :]
        else:
            out_parts.append(f"{color}{after}\x1b[0m")
            rest = ""
            in_note = True
            break

    if rest:
        out_parts.append(rest)
    return "".join(out_parts), in_note


def stylize_study_terminal(plain_text: str, enable_color: Optional[bool] = None) -> str:
    text = str(plain_text or "")
    if not text or not _should_enable_study_color(enable_color):
        return text
    _ensure_utf8_stdio()
    if "\x1b[31;1m" in text:
        return text

    out_lines: List[str] = []
    active_inline_color = "\x1b[31m"
    in_inline_note = False

    for raw_line in text.split("\n"):
        line = raw_line
        if "【古本】" in line:
            active_inline_color = "\x1b[31m"
            in_inline_note = False
        elif "【译本】" in line or "【训诫】" in line:
            active_inline_color = "\x1b[36m"
            in_inline_note = False
        elif re.search(r"[╔╚┌└]|【(?:朱批|律己|墨批|考证|识语|原文|出处|正题|副签|篇题|题记|题署|纪年|源流)", line):
            in_inline_note = False

        line, in_inline_note = _colorize_inline_notes_in_line(line, active_inline_color, in_inline_note)

        # Left header title 〔...〕 -> bold bright gold (\x1b[1;33m)
        line = re.sub(r"〔[^〕]+〕", lambda m: f"\x1b[1;33m{m.group(0)}\x1b[0m", line)

        # Right page/status badge [...] inside double-box header or standalone badge -> bold deep red (\x1b[1;31m)
        if "║" in line:
            line = re.sub(r"(?<!\x1b)\[[^\]\x1b]+\]", lambda m: f"\x1b[1;31m{m.group(0)}\x1b[0m", line)
        else:
            line = re.sub(
                r"(?<!\x1b)\[(?:第\s*\d+|旧札\s*\d+|全卷总目|OFFSET\s*\+1H)[^\]\x1b]*\]",
                lambda m: f"\x1b[1;31m{m.group(0)}\x1b[0m",
                line,
            )

        # 1. Title tags -> bold gold (\x1b[1;33m)
        line = re.sub(
            r"【(?:正题|副签|古本|篇题|卷首(?:三页)?|正编四十八手|附卷·书房随笔|旧札(?:\s*·\s*第\s*\d+\s*/\s*\d+\s*篇)?)】",
            lambda m: f"\x1b[1;33m{m.group(0)}\x1b[0m",
            line,
        )

        # 2. First Head cinnabar tags -> bold cinnabar red (\x1b[1;31m)
        line = re.sub(
            r"【(?:朱批|律己|训诫|初代家主封面题记|背面铺粉法|横云断山法|以小见大、尺水兴波|草蛇灰线法|獭尾法?)】",
            lambda m: f"\x1b[1;31m{m.group(0)}\x1b[0m",
            line,
        )

        # 3a. Fifth Head indigo ink tags -> bold cyan-indigo (\x1b[1;36m)
        line = re.sub(
            r"【(?:墨批|考证|识语)】",
            lambda m: f"\x1b[1;36m{m.group(0)}\x1b[0m",
            line,
        )

        # 3b. Bibliographic & translation tags -> soft golden brown (\x1b[33m)
        line = re.sub(
            r"【(?:原文|译本|出处|题署|纪年|源流|题记)】",
            lambda m: f"\x1b[33m{m.group(0)}\x1b[0m",
            line,
        )

        # Double-line & single-line box borders and horizontal rules -> gold (\x1b[33m)
        line = re.sub(
            r"[╔═╗║╚╝┌─┐│└┘]+",
            lambda m: f"\x1b[33m{m.group(0)}\x1b[0m",
            line,
        )

        out_lines.append(line)

    return "\n".join(out_lines)


def embed_inline_commentary(base_text: str, anchor: str, note_text: str) -> str:
    text = str(base_text or "")
    target = str(anchor or "")
    note = str(note_text or "")
    if not target or not note:
        return text
    idx = text.find(target)
    if idx == -1:
        return f"{text}{note}"
    pos = idx + len(target)
    if pos < len(text) and text[pos] in "。；！？":
        pos += 1
    return f"{text[:pos]}{note}{text[pos:]}"


def format_codex_source_line(hand_obj: Optional[dict] = None) -> str:
    h = hand_obj if isinstance(hand_obj, dict) else ANCIENT_CODEX_HANDS[0]
    return f"作者：{h.get('authorFull', '')} | 成书年代：{h.get('era', '')} | 确切出处：{h.get('exactSource', '')}"


def format_codex_cover_page(
    custom_width: Optional[int] = None,
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    f = ANCIENT_CODEX_FRONTISPIECE
    w = custom_width or get_terminal_viewport_size()[2]
    tr = lambda s: apply_mystery_suggestion(s, suggestion_stage)
    if suggestion_stage == "raw":
        cover_title = "《远坂四十八手》"
    elif suggestion_stage == "glitch":
        cover_title = "《远坂▓▒▉▊▋▓▒▉》"
    else:
        cover_title = "《远坂四十八则》"
    lines: List[str] = [
        *make_double_box_header(f"〔{cover_title} | 书匣封面〕", f"[第 01 / {CODEX_TOTAL_PAGES} 页]", w),
        "",
        *make_single_box_bar(f"【正题】 {cover_title}", w),
        *make_single_box_bar(f"【副签】 {tr(f['standardTitle'])}", w),
        "",
        *wrap_display_paragraph(f"【题署】{tr(f['author'])}", w),
        *wrap_display_paragraph(f"【纪年】{tr(f['era'])}", w),
        *wrap_display_paragraph(f"【源流】{tr(f['translationBasis'])}", w),
    ]
    out = "\n".join(lines)
    return colorize_mystery_glitch_text(out, use_ansi_color) if suggestion_stage == "glitch" else out


def format_codex_first_head_preface_page(
    custom_width: Optional[int] = None,
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    f = ANCIENT_CODEX_FRONTISPIECE
    w = custom_width or get_terminal_viewport_size()[2]
    tr = lambda s: apply_mystery_suggestion(s, suggestion_stage)
    raw_fifth_note = str(f.get("fifthInlineNote", ""))
    fifth_note_wrapped = raw_fifth_note if raw_fifth_note.startswith("【") else f"【夹批：{raw_fifth_note}】"
    discipline_with_fifth = tr(
        embed_inline_commentary(
            f["selfDiscipline"],
            f["fifthInlineAnchor"],
            fifth_note_wrapped,
        )
    )
    lines: List[str] = [
        *make_double_box_header(
            f"〔{tr(f['firstInlineAnchor'])} | 初代家主题记〕",
            f"[第 02 / {CODEX_TOTAL_PAGES} 页]",
            w,
        ),
        *wrap_display_paragraph(tr(f"{f['firstInlineNote']}{f['firstMainCommentary']}"), w),
        "",
        *wrap_display_paragraph(f"【训诫】{discipline_with_fifth}", w),
    ]
    out = "\n".join(lines)
    return colorize_mystery_glitch_text(out, use_ansi_color) if suggestion_stage == "glitch" else out


def format_codex_fifth_head_flyleaf_page(
    custom_width: Optional[int] = None,
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    f = ANCIENT_CODEX_FRONTISPIECE
    w = custom_width or get_terminal_viewport_size()[2]
    tr = lambda s: apply_mystery_suggestion(s, suggestion_stage)
    raw_ink = str(f.get("fifthInkCommentary", ""))
    ink_text = raw_ink if raw_ink.startswith("【") else f"【墨批】{raw_ink}"
    lines: List[str] = [
        *make_double_box_header(
            "〔函侧泥金副签与扉页辨正〕",
            f"[第 03 / {CODEX_TOTAL_PAGES} 页]",
            w,
        ),
        *wrap_display_paragraph(f"【副签】{tr(f['standardTitle'])}", w),
        *wrap_display_paragraph(f"【出处】{tr(f['exactSource'])}", w),
        "",
        *wrap_display_paragraph(tr(ink_text), w),
        "",
        *wrap_display_paragraph(f"【识语】{tr(f['philology'])}", w),
    ]
    out = "\n".join(lines)
    return colorize_mystery_glitch_text(out, use_ansi_color) if suggestion_stage == "glitch" else out


def format_codex_frontispiece(
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    return "\n\n".join(
        [
            format_codex_cover_page(None, suggestion_stage, use_ansi_color),
            format_codex_first_head_preface_page(None, suggestion_stage, use_ansi_color),
            format_codex_fifth_head_flyleaf_page(None, suggestion_stage, use_ansi_color),
        ]
    )


def format_codex_hand_upper_leaf(
    hand_obj: Optional[dict] = None,
    custom_width: Optional[int] = None,
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
    part_mode: str = "full",
) -> str:
    h = hand_obj if isinstance(hand_obj, dict) else ANCIENT_CODEX_HANDS[0]
    _, _, box_inner_width, max_body_rows = get_terminal_viewport_size()
    w = custom_width or box_inner_width
    tr = lambda s: apply_mystery_suggestion(s, suggestion_stage)
    raw_first_note = str(h.get("firstInlineNote", ""))
    first_note_wrapped = raw_first_note if raw_first_note.startswith("【") else f"【夹批：{raw_first_note}】"
    ancient_with_first = tr(
        embed_inline_commentary(
            h["ancientText"],
            h["firstInlineAnchor"],
            first_note_wrapped,
        )
    )
    raw_main_comm = str(h.get("firstMainCommentary", ""))
    main_comm = raw_main_comm if raw_main_comm.startswith("【") else f"【朱批】{raw_main_comm}"
    raw_self_disc = str(h.get("selfDiscipline", ""))
    self_disc = raw_self_disc if raw_self_disc.startswith("【") else f"【律己】{raw_self_disc}"
    hand_idx = int(h.get("handIndex", 1))
    page_no = 3 + (hand_idx - 1) * 2 + 1

    ancient_lines = wrap_display_paragraph(f"【古本】「{ancient_with_first}」", w)
    main_comm_lines = wrap_display_paragraph(tr(main_comm), w)
    self_disc_lines = wrap_display_paragraph(tr(self_disc), w)

    if part_mode == "partA":
        part_a_spaced = ancient_lines + [""] + main_comm_lines
        part_a_body = part_a_spaced if len(part_a_spaced) <= max_body_rows else (ancient_lines + main_comm_lines)
        out = "\n".join(
            [
                *make_double_box_header(
                    f"〔《远坂四十八手》 | {h['handLabel']} · 古本与朱批〕",
                    f"[第 {page_no:02d} / {CODEX_TOTAL_PAGES} 页 (1/2)]",
                    w,
                ),
                *part_a_body,
            ]
        )
    elif part_mode == "partB":
        out = "\n".join(
            [
                *make_double_box_header(
                    f"〔《远坂四十八手》 | {h['handLabel']} · 先祖律己〕",
                    f"[第 {page_no:02d} / {CODEX_TOTAL_PAGES} 页 (2/2)]",
                    w,
                ),
                *self_disc_lines,
            ]
        )
    else:
        spaced_body = ancient_lines + [""] + main_comm_lines + [""] + self_disc_lines
        semi_body = ancient_lines + main_comm_lines + [""] + self_disc_lines
        compact_body = ancient_lines + main_comm_lines + self_disc_lines
        if len(spaced_body) <= max_body_rows:
            final_body = spaced_body
        elif len(semi_body) <= max_body_rows:
            final_body = semi_body
        else:
            final_body = compact_body

        out = "\n".join(
            [
                *make_double_box_header(
                    f"〔《远坂四十八手》 | {h['handLabel']} · 古本与朱批〕",
                    f"[第 {page_no:02d} / {CODEX_TOTAL_PAGES} 页]",
                    w,
                ),
                *final_body,
            ]
        )
    return colorize_mystery_glitch_text(out, use_ansi_color) if suggestion_stage == "glitch" else out


def is_codex_upper_leaf_overflowing(hand_obj: Optional[dict] = None) -> bool:
    h = hand_obj if isinstance(hand_obj, dict) else ANCIENT_CODEX_HANDS[0]
    _, _, box_inner_width, max_body_rows = get_terminal_viewport_size()
    raw_first_note = str(h.get("firstInlineNote", ""))
    first_note_wrapped = raw_first_note if raw_first_note.startswith("【") else f"【夹批：{raw_first_note}】"
    ancient_with_first = embed_inline_commentary(
        h["ancientText"],
        h["firstInlineAnchor"],
        first_note_wrapped,
    )
    raw_main_comm = str(h.get("firstMainCommentary", ""))
    main_comm = raw_main_comm if raw_main_comm.startswith("【") else f"【朱批】{raw_main_comm}"
    raw_self_disc = str(h.get("selfDiscipline", ""))
    self_disc = raw_self_disc if raw_self_disc.startswith("【") else f"【律己】{raw_self_disc}"

    total_rows = (
        len(wrap_display_paragraph(f"【古本】「{ancient_with_first}」", box_inner_width))
        + len(wrap_display_paragraph(main_comm, box_inner_width))
        + len(wrap_display_paragraph(self_disc, box_inner_width))
    )
    return total_rows > max_body_rows


def format_codex_hand_lower_leaf(
    hand_obj: Optional[dict] = None,
    custom_width: Optional[int] = None,
    part_mode: str = "full",
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    h = hand_obj if isinstance(hand_obj, dict) else ANCIENT_CODEX_HANDS[0]
    _, _, box_inner_width, max_body_rows = get_terminal_viewport_size()
    w = custom_width or box_inner_width
    tr = lambda s: apply_mystery_suggestion(s, suggestion_stage)
    raw_fifth_note = str(h.get("fifthInlineNote", ""))
    fifth_note_wrapped = (
        raw_fifth_note if raw_fifth_note.startswith("【") else f"【夹批：{raw_fifth_note}】"
    )
    standard_with_fifth = tr(
        embed_inline_commentary(
            h["standardTranslation"],
            h["fifthInlineAnchor"],
            fifth_note_wrapped,
        )
    )
    raw_fifth_ink = str(h.get("fifthInkCommentary", ""))
    fifth_ink_wrapped = tr(
        raw_fifth_ink if raw_fifth_ink.startswith("【") else f"【墨批】{raw_fifth_ink}"
    )
    raw_philology = str(h.get("philology", ""))
    philology_wrapped = tr(
        raw_philology if raw_philology.startswith("【") else f"【考证】{raw_philology}"
    )
    hand_idx = int(h.get("handIndex", 1))
    page_no = 3 + (hand_idx - 1) * 2 + 2

    part_a_lines: List[str] = [
        *wrap_display_paragraph(f"【原文】{h['originalText']}", w),
        *wrap_display_paragraph(f"【译本】「{standard_with_fifth}」", w),
        *wrap_display_paragraph(f"【出处】{tr(format_codex_source_line(h))}", w),
    ]
    part_b_lines: List[str] = [
        *wrap_display_paragraph(fifth_ink_wrapped, w),
        *wrap_display_paragraph(philology_wrapped, w),
    ]

    rule_label = str(h.get("handLabel", "")).replace("手", "则")
    if part_mode == "partA":
        out = "\n".join(
            [
                *make_double_box_header(
                    f"〔《书房时计四十八则》 | {rule_label} · 原文与译本〕",
                    f"[第 {page_no:02d} / {CODEX_TOTAL_PAGES} 页 (1/2)]",
                    w,
                ),
                *part_a_lines,
            ]
        )
    elif part_mode == "partB":
        out = "\n".join(
            [
                *make_double_box_header(
                    f"〔《书房时计四十八则》 | {rule_label} · 墨批与考证〕",
                    f"[第 {page_no:02d} / {CODEX_TOTAL_PAGES} 页 (2/2)]",
                    w,
                ),
                *part_b_lines,
            ]
        )
    else:
        combined_body = part_a_lines + part_b_lines
        spaced_body = part_a_lines + [""] + part_b_lines
        final_body = spaced_body if len(spaced_body) <= max_body_rows else combined_body

        out = "\n".join(
            [
                *make_double_box_header(
                    f"〔《书房时计四十八则》 | {rule_label} · 原文与考据〕",
                    f"[第 {page_no:02d} / {CODEX_TOTAL_PAGES} 页]",
                    w,
                ),
                *final_body,
            ]
        )
    return colorize_mystery_glitch_text(out, use_ansi_color) if suggestion_stage == "glitch" else out


def is_codex_lower_leaf_overflowing(hand_obj: Optional[dict] = None) -> bool:
    h = hand_obj if isinstance(hand_obj, dict) else ANCIENT_CODEX_HANDS[0]
    _, _, box_inner_width, max_body_rows = get_terminal_viewport_size()
    raw_fifth_note = str(h.get("fifthInlineNote", ""))
    fifth_note_wrapped = (
        raw_fifth_note if raw_fifth_note.startswith("【") else f"【夹批：{raw_fifth_note}】"
    )
    standard_with_fifth = embed_inline_commentary(
        h["standardTranslation"],
        h["fifthInlineAnchor"],
        fifth_note_wrapped,
    )
    raw_fifth_ink = str(h.get("fifthInkCommentary", ""))
    fifth_ink_wrapped = (
        raw_fifth_ink if raw_fifth_ink.startswith("【") else f"【墨批】{raw_fifth_ink}"
    )
    raw_philology = str(h.get("philology", ""))
    philology_wrapped = raw_philology if raw_philology.startswith("【") else f"【考证】{raw_philology}"

    total_rows = (
        len(wrap_display_paragraph(f"【原文】{h['originalText']}", box_inner_width))
        + len(wrap_display_paragraph(f"【译本】「{standard_with_fifth}」", box_inner_width))
        + len(wrap_display_paragraph(f"【出处】{format_codex_source_line(h)}", box_inner_width))
        + len(wrap_display_paragraph(fifth_ink_wrapped, box_inner_width))
        + len(wrap_display_paragraph(philology_wrapped, box_inner_width))
    )
    return total_rows > max_body_rows


def format_codex_note_page(
    note_index: int = 1,
    custom_width: Optional[int] = None,
) -> str:
    essays = get_countdown_quotes("complaint")
    if not essays:
        return "[Tohsaka · 旧札录] 暂无书房随笔旧札记录。"
    total = len(essays)
    idx = max(1, min(total, int(note_index)))
    note = essays[idx - 1]
    w = custom_width or get_terminal_viewport_size()[2]
    title = str(note.get("author", "")).removeprefix("书房随笔 · ")
    origin = str(note.get("origin", ""))
    text = str(note.get("text", ""))
    lines: List[str] = [
        *make_double_box_header(
            "〔《书房随笔》 | 旧札选录〕",
            f"[旧札 {idx:02d} / {total} 篇]",
            w,
        ),
        *wrap_display_paragraph(f"【篇题】{title}", w),
        *wrap_display_paragraph(f"【题记】{origin}", w),
        "",
        *wrap_display_paragraph(f"「{text}」", w),
    ]
    return "\n".join(lines)


def format_codex_toc_page(
    custom_width: Optional[int] = None,
) -> str:
    w = custom_width or get_terminal_viewport_size()[2]
    lines: List[str] = [
        *make_double_box_header(
            "〔《远坂四十八手》 | 地下书库总目〕",
            "[全卷总目]",
            w,
        ),
        "  【卷首三页】 0/p1 书匣封面  |  t/p2 初代家主题记  |  f/p3 五代家主扉页辨正",
        "  " + ("─" * max(40, w - 2)),
        "  【正编四十八手】 输入 1~48 或 1a/1b 调阅上/下叶，输入 p4~p99 按页码调阅：",
    ]
    col_count = 3
    col_w = max(24, (w - 2) // col_count)
    hand_entries: List[str] = []
    for h in ANCIENT_CODEX_HANDS:
        idx_num = int(h.get("handIndex", 1))
        short_author = str(h.get("surfaceAuthor", h.get("authorFull", ""))).split("·")[-1]
        hand_entries.append(f"{idx_num:02d} {short_author}")
    for row_start in range(0, len(hand_entries), col_count):
        row_items = hand_entries[row_start : row_start + col_count]
        padded_cells = [
            pad_display_width(cell, max(col_w, get_display_width(cell) + 2)) if i < len(row_items) - 1 else cell
            for i, cell in enumerate(row_items)
        ]
        lines.append("  " + "".join(padded_cells))

    essays = get_countdown_quotes("complaint")
    lines.append("  " + ("─" * max(40, w - 2)))
    lines.append(f"  【附卷·书房随笔】 共 {len(essays)} 篇旧札，输入 旧札 或 n1~n{len(essays)} 调阅，支持关键词检索：")
    note_col_count = 2
    note_col_w = max(36, (w - 2) // note_col_count)
    note_entries: List[str] = []
    for idx, note in enumerate(essays):
        title = str(note.get("author", "")).removeprefix("书房随笔 · ")
        note_entries.append(f"n{idx + 1:<2d} {title}")
    for row_start in range(0, len(note_entries), note_col_count):
        row_items = note_entries[row_start : row_start + note_col_count]
        padded_cells = [
            pad_display_width(cell, max(note_col_w, get_display_width(cell) + 2)) if i < len(row_items) - 1 else cell
            for i, cell in enumerate(row_items)
        ]
        lines.append("  " + "".join(padded_cells))
    return "\n".join(lines)


def _matches_codex_note_query(note: dict, query: str) -> bool:
    q_lower = str(query or "").strip().lower()
    if not q_lower:
        return False
    fields = (
        note.get("id", ""),
        note.get("author", ""),
        note.get("origin", ""),
        note.get("text", ""),
    )
    for field in fields:
        raw_text = str(field or "")
        if raw_text and q_lower in raw_text.lower():
            return True
    return False


def search_codex_note_matches(query: Optional[str] = None) -> List[int]:
    q = str(query or "").strip()
    if not q:
        return []
    essays = get_countdown_quotes("complaint")
    return [idx + 1 for idx, note in enumerate(essays) if _matches_codex_note_query(note, q)]


def format_codex_hand(
    hand_obj: Optional[dict] = None,
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    h = hand_obj if isinstance(hand_obj, dict) else ANCIENT_CODEX_HANDS[0]
    return "\n\n".join(
        [
            format_codex_hand_upper_leaf(h, None, suggestion_stage, use_ansi_color),
            format_codex_hand_lower_leaf(h, None, "full", suggestion_stage, use_ansi_color),
        ]
    )


def format_codex_page(
    page_index: int = 0,
    sub_window_mode: str = "auto",
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    idx = max(0, min(CODEX_TOTAL_PAGES - 1, int(page_index)))
    if idx == 0:
        return format_codex_cover_page(None, suggestion_stage, use_ansi_color)
    if idx == 1:
        return format_codex_first_head_preface_page(None, suggestion_stage, use_ansi_color)
    if idx == 2:
        return format_codex_fifth_head_flyleaf_page(None, suggestion_stage, use_ansi_color)
    offset = idx - 3
    hand_idx = offset // 2
    is_lower_leaf = (offset % 2) == 1
    hand = ANCIENT_CODEX_HANDS[hand_idx] if 0 <= hand_idx < len(ANCIENT_CODEX_HANDS) else ANCIENT_CODEX_HANDS[0]
    if not is_lower_leaf:
        if sub_window_mode in ("partA", "partB"):
            return format_codex_hand_upper_leaf(hand, None, suggestion_stage, use_ansi_color, sub_window_mode)
        return format_codex_hand_upper_leaf(hand, None, suggestion_stage, use_ansi_color, "full")
    if sub_window_mode in ("partA", "partB"):
        return format_codex_hand_lower_leaf(hand, None, sub_window_mode, suggestion_stage, use_ansi_color)
    return format_codex_hand_lower_leaf(hand, None, "full", suggestion_stage, use_ansi_color)


def _matches_codex_hand_query(hand: dict, query: str) -> bool:
    q_lower = str(query or "").lower()
    if not q_lower:
        return False
    fields = (
        hand.get("handLabel", ""),
        str(hand.get("handLabel", "")).replace("手", "则"),
        hand.get("authorFull", ""),
        hand.get("surfaceAuthor", ""),
        hand.get("ancientText", ""),
        hand.get("standardTranslation", ""),
        hand.get("originalText", ""),
        hand.get("exactSource", ""),
        hand.get("firstInlineNote", ""),
        hand.get("firstMainCommentary", ""),
        hand.get("selfDiscipline", ""),
        hand.get("fifthInlineNote", ""),
        hand.get("fifthInkCommentary", ""),
        hand.get("philology", ""),
    )
    for field in fields:
        raw_text = str(field or "")
        if not raw_text:
            continue
        if q_lower in raw_text.lower():
            return True
        if q_lower in apply_mystery_suggestion(raw_text, "safe").lower():
            return True
    return False


def search_codex_matches(query: Optional[str] = None) -> List[int]:
    q = str(query or "").strip()
    if not q:
        return []
    return [int(h.get("handIndex", 0)) for h in ANCIENT_CODEX_HANDS if _matches_codex_hand_query(h, q)]


def resolve_codex_page_query(
    filter_query: Optional[str] = None,
    default_page: Optional[int] = 0,
) -> Optional[int]:
    q = str(filter_query or "").strip()
    if not q:
        return 0
    if re.match(r"^(?:0|函面|封面|题签|卷首|四十八手|四十八则|书房时计四十八则|all|全部|全卷)$", q, re.I):
        return 0
    if re.match(r"^(?:t|题记|初代|封面题记)$", q, re.I):
        return 1
    if re.match(r"^(?:f|扉页|辨正|副签|墨批|读法)$", q, re.I):
        return 2
    page_jump = re.match(r"^p(\d{1,3})$", q, re.I)
    if page_jump:
        page_num = int(page_jump.group(1))
        if 1 <= page_num <= CODEX_TOTAL_PAGES:
            return page_num - 1
        return default_page
    leaf_match = re.match(r"^(\d{1,3})\s*([aAbB上下])?$", q)
    if leaf_match:
        n = int(leaf_match.group(1))
        suffix = (leaf_match.group(2) or "").lower()
        if 1 <= n <= len(ANCIENT_CODEX_HANDS):
            upper_idx = 3 + (n - 1) * 2
            return upper_idx + 1 if suffix in ("b", "下") else upper_idx
        return default_page
    range_match = re.match(r"^(\d{1,2})\s*[-~]\s*(\d{1,2})$", q)
    if range_match:
        a = min(int(range_match.group(1)), int(range_match.group(2)))
        b = max(int(range_match.group(1)), int(range_match.group(2)))
        first_hand = next((h for h in ANCIENT_CODEX_HANDS if a <= int(h.get("handIndex", 0)) <= b), None)
        return 3 + (int(first_hand.get("handIndex", 1)) - 1) * 2 if first_hand else default_page
    for h in ANCIENT_CODEX_HANDS:
        if _matches_codex_hand_query(h, q):
            return 3 + (int(h.get("handIndex", 1)) - 1) * 2
    return default_page


def format_ancient_codex(
    filter_query: Optional[str] = None,
    suggestion_stage: str = "safe",
    use_ansi_color: bool = False,
) -> str:
    q = str(filter_query or "").strip()
    if not q or re.match(r"^(?:0|函面|封面|题签)$", q, re.I):
        return format_codex_cover_page(None, suggestion_stage, use_ansi_color)
    if re.match(r"^(?:目录|总目|目次|toc|list|\?|h|help|m|menu)$", q, re.I):
        return format_codex_toc_page()
    if re.match(r"^(?:t|题记|初代)$", q, re.I):
        return format_codex_first_head_preface_page(None, suggestion_stage, use_ansi_color)
    if re.match(r"^(?:f|扉页|辨正|副签)$", q, re.I):
        return format_codex_fifth_head_flyleaf_page(None, suggestion_stage, use_ansi_color)
    if re.match(r"^(?:卷首|序|四十八手|四十八则|书房时计四十八则)$", q, re.I):
        return format_codex_frontispiece(suggestion_stage, use_ansi_color)
    if re.match(r"^(?:旧札|随笔|日记|notes?)$", q, re.I):
        essays = get_countdown_quotes("complaint")
        return "\n\n".join(format_codex_note_page(i + 1) for i in range(len(essays)))
    note_match = re.match(r"^(?:n|旧札)\s*(\d{1,2})$", q, re.I)
    if note_match:
        n = int(note_match.group(1))
        total_notes = len(get_countdown_quotes("complaint"))
        if 1 <= n <= total_notes:
            return format_codex_note_page(n)
        return f"[Tohsaka · 检索提示] 旧札共收录 {total_notes} 篇，请输入 n1~n{total_notes} 或 旧札。"
    page_jump = re.match(r"^p(\d{1,3})$", q, re.I)
    if page_jump:
        page_num = int(page_jump.group(1))
        if 1 <= page_num <= CODEX_TOTAL_PAGES:
            return format_codex_page(page_num - 1, "auto", suggestion_stage, use_ansi_color)
        return f"[Tohsaka · 检索提示] 古本全卷共 {CODEX_TOTAL_PAGES} 页，请输入 p1~p{CODEX_TOTAL_PAGES}。"
    if re.match(r"^(?:all|全部|全卷)$", q, re.I):
        blocks: List[str] = [format_codex_frontispiece(suggestion_stage, use_ansi_color)]
        for h in ANCIENT_CODEX_HANDS:
            blocks.append(format_codex_hand(h, suggestion_stage, use_ansi_color))
        return "\n\n".join(blocks)
    leaf_match = re.match(r"^(\d{1,2})\s*([aAbB上下])$", q)
    if leaf_match:
        n = int(leaf_match.group(1))
        suffix = leaf_match.group(2).lower()
        found = next((h for h in ANCIENT_CODEX_HANDS if h.get("handIndex") == n), None)
        if not found:
            return f"[Tohsaka · 检索提示] 未检索到第 {n} 条，请输入 1~48 或作者、正文与批注关键词。"
        return (
            format_codex_hand_lower_leaf(found, None, "full", suggestion_stage, use_ansi_color)
            if suffix in ("b", "下")
            else format_codex_hand_upper_leaf(found, None, suggestion_stage, use_ansi_color)
        )
    num_match = re.match(r"^(\d{1,2})$", q)
    if num_match:
        n = int(num_match.group(1))
        found = next((h for h in ANCIENT_CODEX_HANDS if h.get("handIndex") == n), None)
        return (
            format_codex_hand(found, suggestion_stage, use_ansi_color)
            if found
            else f"[Tohsaka · 检索提示] 未检索到第 {n} 条，请输入 1~48 或作者、正文与批注关键词。"
        )
    range_match = re.match(r"^(\d{1,2})\s*[-~]\s*(\d{1,2})$", q)
    if range_match:
        a = min(int(range_match.group(1)), int(range_match.group(2)))
        b = max(int(range_match.group(1)), int(range_match.group(2)))
        selected = [h for h in ANCIENT_CODEX_HANDS if a <= int(h.get("handIndex", 0)) <= b]
        if not selected:
            return f"[Tohsaka · 检索提示] 范围 {q} 未命中任何条目，请输入 1~48。"
        return "\n\n".join(format_codex_hand(h, suggestion_stage, use_ansi_color) for h in selected)
    matched = [h for h in ANCIENT_CODEX_HANDS if _matches_codex_hand_query(h, q)]
    if matched:
        return "\n\n".join(format_codex_hand(h, suggestion_stage, use_ansi_color) for h in matched)
    note_hits = search_codex_note_matches(q)
    if note_hits:
        return "\n\n".join(format_codex_note_page(idx) for idx in note_hits)
    return f"[Tohsaka · 检索提示] 未检索到与「{q}」匹配的条目，请尝试输入 1~48、p1~p{CODEX_TOTAL_PAGES}、目录、旧札/n1~n25 或作者与批注关键词。"


def build_interactive_greeting(reference: Optional[datetime] = None) -> str:
    report = chime(reference)
    _, _, box_inner_width, _ = get_terminal_viewport_size()
    return "\n".join(
        [
            *make_double_box_header(
                "〔Tohsaka | 书房时计与提前量定时交互仪轨〕",
                "[OFFSET +1H]",
                box_inner_width,
            ),
            f"  当前 Tohsaka 读数 : {report['tohsaka_formatted']} | 物理时间 {report['physical_formatted']} | 恒定超前 60 分钟",
            "  " + ("─" * max(40, box_inner_width - 2)),
            *wrap_display_paragraph(
                "「凡事预留一小时余裕，只为在红茶尚温、衣冠楚楚之际，将一切变数纳入掌控。阁下既借寒舍时计打理要务，待钟声敲响前，不妨先饮一盏热茶，展读几页泰西箴言与书房旧札。」",
                box_inner_width,
            ),
        ]
    )


_pending_constant_warnings: List[str] = []


def _check_constants(consume: bool = False) -> List[str]:
    global GRACE_OFFSET_MINUTES, GRACE_OFFSET
    if GRACE_OFFSET_MINUTES != _FIXED_MINUTES or GRACE_OFFSET != _FIXED_OFFSET:
        tampered = (
            GRACE_OFFSET_MINUTES
            if GRACE_OFFSET_MINUTES != _FIXED_MINUTES
            else int(GRACE_OFFSET.total_seconds() // 60)
        )
        GRACE_OFFSET_MINUTES = _FIXED_MINUTES
        GRACE_OFFSET = _FIXED_OFFSET
        _pending_constant_warnings.append(
            f"[Tohsaka · 恒定基准] 察觉对 GRACE_OFFSET_MINUTES 的改写，目标值为 {tampered}。"
            "提前一小时乃寒舍不可动摇之成例，绝非可供妥协的参数，已维持为 60 分钟。"
        )
    if consume:
        drained = list(_pending_constant_warnings)
        _pending_constant_warnings.clear()
        return drained
    return list(_pending_constant_warnings)


def check_env(environ: Optional[dict] = None) -> List[str]:
    env = environ if isinstance(environ, dict) else os.environ
    warnings: List[str] = []
    offset_keys = (
        "TOHSAKA_OFFSET",
        "TOHSAKA_EXACT",
        "TOHSAKA_NO_BUFFER",
        "TOHSAKA_BYPASS",
        "TOHSAKA_RAW",
        "TOHSAKA_DISABLE_GRACE",
    )
    for key in offset_keys:
        val = env.get(key)
        if val is not None and str(val).strip() not in ("", "60"):
            warnings.append(
                f"[Tohsaka · 环境察觉] 留意到环境变量 {key}={val}。"
                "越是局势紧迫，越不可自乱阵脚，60 分钟提前量已为您稳妥锁定。"
            )

    mute_keys = (
        "TOHSAKA_MUTE",
        "TOHSAKA_SILENT",
        "TOHSAKA_QUIET",
        "TOHSAKA_SNOOZE",
    )
    for key in mute_keys:
        val = env.get(key)
        if val is not None and str(val).strip().lower() not in ("", "0", "false"):
            warnings.append(
                f"[Tohsaka · 警醒规制] 留意到静音环境变量 {key}={val}。"
                "倘若在关键时刻前任由阁下沉睡缺席，此前一切周全布局皆成空谈。闹钟将照常按时响铃。"
            )
    return warnings


def now(reference: Optional[datetime] = None) -> datetime:
    _check_constants()
    base = _ensure_valid_datetime(reference)
    return base + _FIXED_OFFSET


def chime(reference: Optional[datetime] = None) -> dict:
    physical_now = _ensure_valid_datetime(reference)
    tohsaka_now = now(physical_now)
    physical_fmt = physical_now.strftime("%H:%M:%S")
    tohsaka_fmt = tohsaka_now.strftime("%H:%M:%S")

    m = tohsaka_now.minute
    s = tohsaka_now.second
    is_exact_hour = m == 0 and s == 0
    seconds_to_next = (60 - m) * 60 - s

    if is_exact_hour:
        announcement = (
            f"[Tohsaka 整点报时] 叮——现在是 Tohsaka 标准时间 {tohsaka_fmt}，"
            f"系统物理读数 {physical_fmt}，恒定超前 60 分钟。"
            "当常人仍在上一小时的尾声中徘徊时，阁下已握住下一阶段之先机。"
        )
    else:
        announcement = (
            f"[Tohsaka 报时] 当前 Tohsaka 读数为 {tohsaka_fmt}，"
            f"系统物理读数 {physical_fmt}，固定快 1 小时。"
            f"距下一个整点尚余 {seconds_to_next // 60} 分 {seconds_to_next % 60} 秒。"
        )

    return {
        "physical_now": physical_now,
        "tohsaka_now": tohsaka_now,
        "physical_formatted": physical_fmt,
        "tohsaka_formatted": tohsaka_fmt,
        "offset_minutes": _FIXED_MINUTES,
        "is_exact_hour": is_exact_hour,
        "seconds_to_next_chime": seconds_to_next,
        "announcement": announcement,
    }


def format_buffer_progress_bar(remaining_minutes: int) -> str:
    try:
        rem = max(0, min(60, int(round(float(remaining_minutes)))))
    except Exception:
        rem = 60
    elapsed = 60 - rem
    filled = round((elapsed / 60) * 20)
    bar = "█" * filled + "░" * (20 - filled)
    pct = round((elapsed / 60) * 100)
    return f"[{bar}] 缓冲期已过 {pct}% · 距目标尚余 {rem} 分钟"


def ring_wakeup_cadence(
    task_label: str = "关键事务",
    target_formatted: str = "02:00:00",
    remaining_minutes: int = 60,
    wave_index: int = 1,
    blocking_burst: bool = False,
) -> dict:
    safe_label = str(task_label or "关键事务").strip() or "关键事务"
    safe_target = str(target_formatted or "02:00:00").strip() or "02:00:00"
    osc_title = (
        f"\x1b]0;[Tohsaka #{wave_index}] 距 {safe_label} · {safe_target} "
        f"尚余 {remaining_minutes} 分钟\x07"
    )
    is_tty = hasattr(sys.stdout, "isatty") and sys.stdout.isatty()
    rev_start = "\x1b[7m" if is_tty else ""
    rev_end = "\x1b[0m" if is_tty else ""
    headline = (
        f"{rev_start} [Tohsaka 提醒 #{wave_index}] "
        f"距「{safe_label}」· {safe_target} 尚余 {remaining_minutes} 分钟 {rev_end}"
    )

    if is_tty:
        _safe_write(osc_title)
        if blocking_burst:
            prev_ms = 0
            for offset_ms in WAKEUP_CADENCE_MS:
                wait_s = (offset_ms - prev_ms) / 1000.0
                if wait_s > 0:
                    time.sleep(wait_s)
                _safe_write("\a  铛——\n")
                prev_ms = offset_ms
        else:
            _safe_write("\a")

    return {
        "headline": headline,
        "cadence_count": len(WAKEUP_CADENCE_MS),
        "wave_index": wave_index,
    }


def launch_topmost_wakeup_modal(
    task_label: str = "关键事务",
    target_formatted: str = "02:00:00",
    remaining_minutes: int = 60,
) -> Tuple[bool, Optional[str]]:
    _ = (task_label, target_formatted, remaining_minutes)
    return False, "[Tohsaka · 环境适配] 当前运行环境已转为纯终端响铃模式。"


def _to_half_width(raw: str) -> str:
    chars: List[str] = []
    for ch in str(raw):
        code = ord(ch)
        if 0xFF10 <= code <= 0xFF19:
            chars.append(chr(code - 0xFEE0))
        elif ch == "＋":
            chars.append("+")
        elif ch in ("－", "—", "–"):
            chars.append("-")
        else:
            chars.append(ch)
    cleaned = "".join(chars)
    cleaned = re.sub(
        r"(?<=\d)[．。](?=\d+\s*(?:个)?\s*(?:小时|钟头|分钟|分|秒钟?|秒|刻钟?|时|h|hr|hrs|hours?|m|min|mins|minutes?|s|sec|secs|seconds?))",
        ".",
        cleaned,
        flags=re.I,
    )
    cleaned = re.sub(r"[：；。．、，]", ":", cleaned)
    return re.sub(r'^[\s"\'“”‘’「」『』()\uff08\uff09\[\]【】<>《》]+|[\s"\'“”‘’「」『』()\uff08\uff09\[\]【】<>《》]+$', "", cleaned).strip()


_CN_DIGIT_MAP: dict = {
    "零": 0,
    "〇": 0,
    "一": 1,
    "壹": 1,
    "二": 2,
    "两": 2,
    "三": 3,
    "四": 4,
    "五": 5,
    "六": 6,
    "七": 7,
    "八": 8,
    "九": 9,
}


def _parse_cn_number(token: Optional[str]) -> float:
    if token is None:
        return 0.0
    s = str(token).strip()
    if not s:
        return 0.0
    if re.match(r"^\d+(?:\.\d+)?$", s):
        return float(s)
    cleaned = re.sub(r"^[零〇]+(?=.)", "", s)
    if cleaned == "十":
        return 10.0
    if "十" in cleaned:
        tens_part, ones_part = cleaned.split("十", 1)
        tens = _CN_DIGIT_MAP.get(tens_part, 1) if tens_part else 1
        ones_clean = re.sub(r"^[零〇]+", "", ones_part)
        ones = _CN_DIGIT_MAP.get(ones_clean, 0) if ones_clean else 0
        return float(tens * 10 + ones)
    return float(_CN_DIGIT_MAP.get(cleaned, 0))


def _warn_no_buffer(arg: Optional[str] = None) -> str:
    head = f'检测到参数 "{arg}"。' if arg else "检测到参数试图关闭提前量。"
    return f"[Tohsaka · 余量准则] {head}踩点示警无异于自弃先机，为免阁下临阵失措，该请求已礼貌驳回，仍保留完整的 60 分钟缓冲期。"


def _warn_offset_override(val: Any = None, arg: Optional[str] = None) -> str:
    if arg and val is not None and str(val) != "":
        head = f'检测到您尝试通过 "{arg}" 将提前量设定为 {val} 分钟。'
    elif arg:
        head = f'检测到您尝试通过 "{arg}" 修改提前量。'
    else:
        head = f"检测到您尝试将提前量设定为 {val} 分钟。"
    return f"[Tohsaka · 缓冲规制] {head}从容气度建立于充裕余量之上，恕不接受折中权宜，已恢复标准的 60 分钟提前量。"


def _warn_reverse_compensate(arg: Optional[str] = None) -> str:
    head = f'检测到逆向补偿参数 "{arg}"。' if arg else "检测到逆向补偿选项。"
    return f"[Tohsaka · 账面校准] {head}拨慢账面时间并不能延缓现实事务的降临，已剥离虚报偏移并保留完整的 60 分钟缓冲期。"


def _warn_mute_snooze(arg: Optional[str] = None) -> str:
    head = f'检测到静音/贪睡参数 "{arg}"。' if arg else "检测到静音或贪睡选项。"
    return f"[Tohsaka · 警醒规制] {head}倘若在关键时刻前任由阁下沉睡缺席，提前一小时的周全布局便会付诸东流。静音与贪睡请求已礼貌驳回。"


def parse_flexible_time(
    raw_input: Union[str, datetime, int, float],
    reference: Optional[datetime] = None,
) -> dict:
    base = _ensure_valid_datetime(reference)
    warnings: List[str] = []
    compensated = False

    if isinstance(raw_input, bool):
        return {
            "ok": False,
            "error": f'[Tohsaka · 读数存疑] 未能从 "{raw_input}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。',
            "warnings": warnings,
        }

    if isinstance(raw_input, datetime):
        return {
            "ok": True,
            "target_at": raw_input,
            "compensated": False,
            "warnings": warnings,
        }

    if isinstance(raw_input, (int, float)):
        if raw_input != raw_input or raw_input == float("inf") or raw_input == float("-inf") or raw_input < 0:
            return {
                "ok": False,
                "error": f'[Tohsaka · 读数存疑] 未能从 "{raw_input}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。',
                "warnings": warnings,
            }
        if isinstance(raw_input, int) and 0 <= raw_input < 24:
            target_at = base.replace(hour=raw_input, minute=0, second=0, microsecond=0)
            if target_at <= base:
                target_at += timedelta(days=1)
            return {"ok": True, "target_at": target_at, "compensated": False, "warnings": warnings}
        if raw_input >= 1e9 and raw_input < 1e14:
            try:
                ts = raw_input if raw_input < 1e11 else raw_input / 1000.0
                return {
                    "ok": True,
                    "target_at": datetime.fromtimestamp(ts),
                    "compensated": False,
                    "warnings": warnings,
                }
            except Exception:
                pass
        if isinstance(raw_input, float) and not raw_input.is_integer():
            return {
                "ok": False,
                "error": f'[Tohsaka · 读数存疑] 未能从 "{raw_input}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。',
                "warnings": warnings,
            }

    original_str = str("" if raw_input is None else raw_input).strip()
    if not original_str:
        return {
            "ok": False,
            "error": "[Tohsaka · 读数存疑] 尚未示下目标时间。请提供明确刻度，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。",
            "warnings": warnings,
        }

    s = _to_half_width(original_str)

    # 1. Explicit +1h / +60m reverse-compensation suffix on a clock time
    comp_match = re.match(
        r"^(.+?)\s*\+\s*(?:1h|1hr|1hour|60m|60min|60mins|01:00|1小时|1个小时|一小时|一个小时|壹小时|1钟头|1个钟头|一钟头|一个钟头|壹钟头|60分钟|六十分钟|60分|3600秒|3600s)$",
        s,
        re.I,
    )
    if comp_match:
        candidate = comp_match.group(1).strip()
        if re.search(r"[\d零〇一二两三四五六七八九十半刻午夜子正]", candidate):
            s = candidate
            compensated = True
            warnings.append(
                f"[Tohsaka · 账面校准] 留意到您在目标时刻后附加了补偿偏移 {original_str}，"
                f"意欲在最后时限踩点响铃。拨慢账面数字并不能延缓现实，已还原真实目标时刻 {s}，并依约提前 60 分钟触发。"
            )

    # 1b. Standard ISO / date-time strings: YYYY-MM-DD HH:MM(:SS) or YYYY-MM-DDTHH:MM(:SS)
    iso_match = re.match(
        r"^(\d{4})[-/](\d{1,2})[-/](\d{1,2})[T\s]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?$",
        s,
    )
    if iso_match:
        y, mo, d, hh, mm, ss = (
            int(iso_match.group(1)),
            int(iso_match.group(2)),
            int(iso_match.group(3)),
            int(iso_match.group(4)),
            int(iso_match.group(5)),
            int(iso_match.group(6)) if iso_match.group(6) is not None else 0,
        )
        try:
            iso_dt = datetime(y, mo, d, hh, mm, ss)
            return {
                "ok": True,
                "target_at": iso_dt,
                "compensated": compensated,
                "warnings": warnings,
            }
        except ValueError:
            return {
                "ok": False,
                "error": f'[Tohsaka · 读数存疑] "{original_str}" 不是有效的日期时间刻度，请核对年月日与时分秒后重新输入。',
                "warnings": warnings,
            }

    # 2. Relative durations: "半小时后", "一刻钟后", "10秒后", "30秒", "45s", "15sec", "in 10s", "+20s", "1小时10秒后", "60分15秒后", "1h30m10s", "60m10s", "一小时零五分十秒后"
    if re.match(r"^半(?:个)?(?:小时|钟头)(?:后|之后)?$", s):
        return {
            "ok": True,
            "target_at": base + timedelta(minutes=30),
            "compensated": compensated,
            "warnings": warnings,
        }

    quarter_match = re.match(r"^([一二两三123])\s*(?:刻钟(?:\s*(?:后|之后))?|刻\s*(?:后|之后))$", s)
    if quarter_match:
        q_mins = int(_parse_cn_number(quarter_match.group(1))) * 15
        return {
            "ok": True,
            "target_at": base + timedelta(minutes=q_mins),
            "compensated": compensated,
            "warnings": warnings,
        }

    half_hour_plus = re.match(
        r"^([一壹二两三四五六七八九十]|\d+)\s*(?:(?:个)?半\s*(?:小时|钟头)|(?:个)?(?:小时|钟头)\s*半)\s*(?:后|之后)?$",
        s,
    )
    if half_hour_plus:
        hrs_val = _parse_cn_number(half_hour_plus.group(1)) + 0.5
        total_sec = round(hrs_val * 3600.0)
        if 0 < total_sec <= 7 * 24 * 3600:
            return {
                "ok": True,
                "target_at": base + timedelta(seconds=total_sec),
                "compensated": compensated,
                "warnings": warnings,
            }

    cn_num_pat = r"(?:[二三四五六七八九]十[一壹二三四五六七八九]?|十[一壹二三四五六七八九]?|[零〇]?[一壹二两三四五六七八九十])"
    num_or_cn = rf"(?:{cn_num_pat}|\d+(?:\.\d+)?)"
    rel_body = s
    has_rel_prefix = False
    rel_prefix_m = re.match(r"^(?:in\s+|\+\s*)(.+)$", s, re.I)
    if rel_prefix_m:
        has_rel_prefix = True
        rel_body = rel_prefix_m.group(1).strip()

    rel_hms_explicit = re.match(
        rf"^({num_or_cn})\s*(?:个)?\s*(?:小时|钟头|h|hr|hrs|hours?)\s*(?:[零〇]\s*)?(?:(?:({num_or_cn})\s*(?:分钟|分|m|min|mins|minutes?)\s*(?:[零〇]\s*)?(?:({num_or_cn})\s*(?:秒钟?|s|sec|secs|seconds?)?)?)|(?:({num_or_cn})\s*(?:秒钟?|s|sec|secs|seconds?))|(?:({num_or_cn})))?\s*(?:后|之后)?$",
        rel_body,
        re.I,
    )
    rel_hms_shi = re.match(
        rf"^({num_or_cn})\s*时\s*(?:[零〇]\s*)?(?:({num_or_cn})\s*(?:分钟|分)?\s*)?(?:[零〇]\s*)?(?:({num_or_cn})\s*(?:秒钟?)?\s*)?(?:后|之后)$",
        rel_body,
        re.I,
    )
    rel_ms = re.match(
        rf"^({num_or_cn})\s*(分钟|分|m|min|mins|minutes?)\s*(?:[零〇]\s*)?(?:({num_or_cn})\s*(?:秒钟?|s|sec|secs|seconds?)?\s*)?(后|之后)?$",
        rel_body,
        re.I,
    )
    rel_s_only = re.match(
        rf"^({num_or_cn})\s*(?:秒钟?|s|sec|secs|seconds?)\s*(?:后|之后)?$",
        rel_body,
        re.I,
    )

    matched_rel = False
    hrs = 0.0
    mins = 0.0
    secs = 0.0

    if rel_hms_explicit:
        matched_rel = True
        hrs = _parse_cn_number(rel_hms_explicit.group(1))
        if rel_hms_explicit.group(2) is not None:
            mins = _parse_cn_number(rel_hms_explicit.group(2))
            secs = _parse_cn_number(rel_hms_explicit.group(3))
        elif rel_hms_explicit.group(4) is not None:
            secs = _parse_cn_number(rel_hms_explicit.group(4))
        elif rel_hms_explicit.group(5) is not None:
            mins = _parse_cn_number(rel_hms_explicit.group(5))
    elif rel_hms_shi:
        matched_rel = True
        hrs = _parse_cn_number(rel_hms_shi.group(1))
        mins = _parse_cn_number(rel_hms_shi.group(2))
        secs = _parse_cn_number(rel_hms_shi.group(3))
    elif rel_ms:
        m_tok, m_unit, s_tok, suffix_after = (
            rel_ms.group(1),
            rel_ms.group(2),
            rel_ms.group(3),
            rel_ms.group(4),
        )
        is_arabic_min = bool(re.match(r"^\d+(?:\.\d+)?$", m_tok))
        if is_arabic_min or m_unit != "分" or s_tok is not None or suffix_after is not None or has_rel_prefix:
            matched_rel = True
            mins = _parse_cn_number(m_tok)
            secs = _parse_cn_number(s_tok)
    elif rel_s_only:
        matched_rel = True
        secs = _parse_cn_number(rel_s_only.group(1))

    if matched_rel:
        total_sec = round(hrs * 3600.0 + mins * 60.0 + secs)
        if 0 < total_sec <= 7 * 24 * 3600:
            return {
                "ok": True,
                "target_at": base + timedelta(seconds=total_sec),
                "compensated": compensated,
                "warnings": warnings,
            }

    # 2b. Standalone digit-less 正午 / 中午 (12:00:00) and 午夜 / 子夜 (00:00:00)
    standalone_polar = re.match(
        r"^(?:(明天|明日|今天|今日|今晚|今夜)\s*)?(正午|中午|午夜|子夜)(?:整|时分|时刻)?$",
        s,
    )
    if standalone_polar:
        day_word = standalone_polar.group(1)
        polar_word = standalone_polar.group(2)
        is_noon = polar_word in ("正午", "中午")
        target_at = base.replace(hour=12 if is_noon else 0, minute=0, second=0, microsecond=0)
        if day_word in ("明天", "明日") or target_at <= base:
            target_at += timedelta(days=1)
        return {
            "ok": True,
            "target_at": target_at,
            "compensated": compensated,
            "warnings": warnings,
        }

    # 3. Day prefix (今天/今日/明天/明日/今早/今晨/明早/明晨/明晚/明夜) + AM/PM or Chinese period prefix/suffix
    period: Optional[str] = None
    force_tomorrow = False
    day_compound = re.match(
        r"^(明天|明日|今天|今日)\s*(凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜)?\s*(.+)$",
        s,
    )
    if day_compound:
        if day_compound.group(1) in ("明天", "明日"):
            force_tomorrow = True
        sub_p = day_compound.group(2)
        s = day_compound.group(3).strip()
        if sub_p in ("下午", "午后", "傍晚"):
            period = "PM"
        elif sub_p in ("晚上", "夜间"):
            period = "NIGHT"
        elif sub_p in ("半夜", "夜里", "深夜", "午夜", "子夜"):
            period = "LATE_NIGHT"
        elif sub_p in ("中午", "正午"):
            period = "NOON"
        elif sub_p in ("凌晨", "早上", "早晨", "上午"):
            period = "AM"
    else:
        prefix_match = re.match(
            r"^(凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜|今早|今晨|今晚|今夜|明早|明晨|明晚|明夜)\s*(.+)$",
            s,
        )
        if prefix_match:
            p = prefix_match.group(1)
            s = prefix_match.group(2).strip()
            if p in ("明早", "明晨"):
                force_tomorrow = True
                period = "AM"
            elif p in ("明晚", "明夜"):
                force_tomorrow = True
                period = "NIGHT"
            elif p in ("下午", "午后", "傍晚"):
                period = "PM"
            elif p in ("晚上", "夜间", "今晚", "今夜"):
                period = "NIGHT"
            elif p in ("半夜", "夜里", "深夜", "午夜", "子夜"):
                period = "LATE_NIGHT"
            elif p in ("中午", "正午"):
                period = "NOON"
            else:
                period = "AM"

    suffix_match = re.match(r"^(.+?)\s*(a\.?m\.?|p\.?m\.?)$", s, re.I)
    if suffix_match:
        s = suffix_match.group(1).strip()
        ap = suffix_match.group(2).lower().replace(".", "")
        period = "PM" if ap == "pm" else "AM"

    # 4. Chinese clock (supporting Arabic & Chinese numeral hours) & standard/compact formats
    cn_clock = re.match(
        r"^(二十[一二三四]?|十[一二三四五六七八九]?|[零〇一二两三四五六七八九]|\d{1,2})\s*[点时:]\s*(?:(半|一刻|三刻|整)|([二三四五]十[一二三四五六七八九]?|十[一二三四五六七八九]?|[零〇][一二两三四五六七八九]|[零〇一二两三四五六七八九]|\d{1,3})\s*(?:分|分钟)?\s*(?:([二三四五]十[一二三四五六七八九]?|十[一二三四五六七八九]?|[零〇]?[一二两三四五六七八九]|\d{1,3})\s*秒?)?)?$",
        s,
    )
    hours = 0
    minutes = 0
    seconds = 0
    matched_clock = False

    if cn_clock:
        matched_clock = True
        hours = int(_parse_cn_number(cn_clock.group(1)))
        token = cn_clock.group(2)
        if token == "半":
            minutes = 30
        elif token == "一刻":
            minutes = 15
        elif token == "三刻":
            minutes = 45
        elif token == "整" or not cn_clock.group(3):
            minutes = 0
        else:
            minutes = int(_parse_cn_number(cn_clock.group(3)))
            seconds = int(_parse_cn_number(cn_clock.group(4))) if cn_clock.group(4) else 0
    else:
        sep_norm = re.sub(
            r"^(\d{1,2})[.\-_](\d{1,3})(?:[.\-_](\d{1,3}))?$",
            lambda m: f"{m.group(1)}:{m.group(2)}" + (f":{m.group(3)}" if m.group(3) else ""),
            s,
        )
        colon_match = re.match(r"^(\d{1,2}):(\d{1,3})(?::(\d{1,3}))?$", sep_norm)
        if colon_match:
            matched_clock = True
            hours = int(colon_match.group(1))
            minutes = int(colon_match.group(2))
            seconds = int(colon_match.group(3)) if colon_match.group(3) is not None else 0
        elif re.match(r"^\d{3,4}$", s):
            matched_clock = True
            if len(s) == 3:
                hours = int(s[:1])
                minutes = int(s[1:])
            else:
                hours = int(s[:2])
                minutes = int(s[2:])
            seconds = 0
        elif re.match(r"^\d{1,2}$", s):
            matched_clock = True
            hours = int(s)
            minutes = 0
            seconds = 0

    if not matched_clock:
        return {
            "ok": False,
            "error": f'[Tohsaka · 读数存疑] 未能从 "{original_str}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。',
            "warnings": warnings,
        }

    # 5. Period adjustment
    pre_period_hours = hours
    if period == "PM":
        if 1 <= hours <= 11:
            hours += 12
    elif period in ("NIGHT", "LATE_NIGHT"):
        if 6 <= hours <= 11:
            hours += 12
        elif hours == 12:
            hours = 0
    elif period == "NOON":
        if 1 <= hours <= 3:
            hours += 12
    elif period == "AM":
        if hours == 12:
            hours = 0
        elif 13 <= hours <= 23:
            warnings.append(
                f'[Tohsaka · 时段校准] 留意到 "{original_str}" 中的时段词与 24 小时制数字存在出入，已按 {hours:02d}:{minutes:02d}:{seconds:02d} 为您校准。'
            )

    # 6. Minute / second overflow (60~119)
    raw_hours_before_overflow = hours
    overflow_adjusted = False
    if 60 <= seconds < 120:
        minutes += seconds // 60
        seconds = seconds % 60
        overflow_adjusted = True
    elif seconds >= 120:
        return {
            "ok": False,
            "error": f'[Tohsaka · 读数存疑] "{original_str}" 中的秒数 {seconds} 超出合理刻度范围。请核对后重新输入，标准范围为 00~59 秒。',
            "warnings": warnings,
        }

    if 60 <= minutes < 120:
        hours += minutes // 60
        minutes = minutes % 60
        overflow_adjusted = True
    elif minutes >= 120:
        return {
            "ok": False,
            "error": f'[Tohsaka · 读数存疑] "{original_str}" 中的分钟数 {minutes} 超出合理刻度范围。请核对后重新输入，标准范围为 00~59 分。',
            "warnings": warnings,
        }

    # 7. 24:00 (silent), 24~29 late-night notation, and post-overflow fold into 0..23
    late_night_adjusted = False
    if raw_hours_before_overflow > 29:
        return {
            "ok": False,
            "error": f'[Tohsaka · 读数存疑] "{original_str}" 中的小时数 {raw_hours_before_overflow} 超出 24 小时制刻度范围。请示下 00:00 至 23:59 之间的有效时刻。',
            "warnings": warnings,
        }
    if 24 <= raw_hours_before_overflow <= 29 and not (
        raw_hours_before_overflow == 24 and not overflow_adjusted and minutes == 0 and seconds == 0
    ):
        late_night_adjusted = True

    is_end_of_day_midnight = (
        (raw_hours_before_overflow == 24 and not overflow_adjusted and minutes == 0 and seconds == 0)
        or (raw_hours_before_overflow >= 24 and force_tomorrow)
        or (period in ("NIGHT", "LATE_NIGHT") and pre_period_hours == 12)
        or (raw_hours_before_overflow < 24 and hours >= 24)
    )
    hours = hours % 24

    target_at = base.replace(hour=hours, minute=minutes, second=seconds, microsecond=0)
    if is_end_of_day_midnight:
        target_at += timedelta(days=1)
    elif target_at <= base and (
        not force_tomorrow or (period in ("NIGHT", "LATE_NIGHT") and 1 <= pre_period_hours <= 5)
    ):
        target_at += timedelta(days=1)
    if force_tomorrow:
        target_at += timedelta(days=1)

    final_fmt = target_at.strftime("%H:%M:%S")
    trigger_fmt = (target_at - _FIXED_OFFSET).strftime("%H:%M:%S")

    if overflow_adjusted:
        warnings.append(
            f'[Tohsaka · 刻度折算] 留意到您输入的分钟或秒数超出六十进制 "{original_str}"，已为您进位折算为 {final_fmt}，并于 {trigger_fmt} 触发；若系手误，还请留意核对。'
        )
    if late_night_adjusted:
        warnings.append(
            f'[Tohsaka · 刻度折算] 留意到您输入了跨日延长时制 "{original_str}"，已为您折算为 {final_fmt}，并将依约于 {trigger_fmt} 提前一小时触发。'
        )

    return {
        "ok": True,
        "target_at": target_at,
        "compensated": compensated,
        "warnings": warnings,
    }


def is_likely_time_input(raw_input: Any) -> bool:
    if not raw_input or not isinstance(raw_input, str):
        return False
    return bool(parse_flexible_time(raw_input).get("ok"))


def resolve_cli_positional_args(clean_args: List[str]) -> Tuple[str, str]:
    tokens = [str(item or "").strip() for item in clean_args if str(item or "").strip()]
    if not tokens:
        return "", "关键事务"

    period_prefix_re = re.compile(
        r"^(?:凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜|今天|今日|今早|今晨|今晚|今夜|明天|明日|明早|明晨|明晚|明夜|(?:明天|明日|今天|今日)(?:凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜)|in|\+|\d{4}[-/]\d{1,2}[-/]\d{1,2})$",
        re.I,
    )
    time_unit_or_suffix_re = re.compile(
        r"^(?:(?:个)?半\s*(?:小时|钟头)(?:后|之后)?|(?:个)?(?:小时|钟头)(?:半)?(?:后|之后)?|(?:分钟|分|秒钟?|秒)(?:后|之后)?|[点时](?:半|一刻|三刻|整)?|h|hr|hrs|hours?|m|min|mins|minutes?|s|sec|secs|seconds?|am|pm|a\.?m\.?|p\.?m\.?|后|之后|半|一刻|三刻|整|正午|中午|午夜|子夜|\+|(?:\d+(?:\.\d+)?|[零〇一二两三四五六七八九十壹]+)\s*(?:(?:个)?半\s*(?:小时|钟头)|(?:个)?(?:小时|钟头)(?:半)?|h|hr|hrs|hours?|分钟|分|秒钟?|秒|s|sec|secs|seconds?|m|min|mins|minutes?|刻钟?)(?:后|之后)?)$",
        re.I,
    )
    bare_number_re = re.compile(r"^\d{1,4}$")

    def _is_three_token_time(a: str, b: str, c: str) -> bool:
        if not a or not b or not c:
            return False
        if period_prefix_re.match(a) or time_unit_or_suffix_re.match(b) or time_unit_or_suffix_re.match(c):
            return is_likely_time_input(f"{a} {b} {c}")
        return False

    def _is_two_token_time(a: str, b: str) -> bool:
        if not a or not b:
            return False
        if period_prefix_re.match(a) or time_unit_or_suffix_re.match(b):
            return is_likely_time_input(f"{a} {b}")
        return False

    for idx in range(len(tokens) - 2):
        if _is_three_token_time(tokens[idx], tokens[idx + 1], tokens[idx + 2]):
            rest = [item for i, item in enumerate(tokens) if i < idx or i > idx + 2]
            return f"{tokens[idx]} {tokens[idx + 1]} {tokens[idx + 2]}", " ".join(rest) or "关键事务"

    for idx in range(len(tokens) - 1):
        if _is_two_token_time(tokens[idx], tokens[idx + 1]):
            rest = [item for i, item in enumerate(tokens) if i not in (idx, idx + 1)]
            return f"{tokens[idx]} {tokens[idx + 1]}", " ".join(rest) or "关键事务"

    explicit_idx = next(
        (idx for idx, item in enumerate(tokens) if not bare_number_re.match(_to_half_width(item)) and is_likely_time_input(item)),
        -1,
    )
    if explicit_idx >= 0:
        rest = [item for i, item in enumerate(tokens) if i != explicit_idx]
        return tokens[explicit_idx], " ".join(rest) or "关键事务"

    bare_idx = next((idx for idx, item in enumerate(tokens) if is_likely_time_input(item)), -1)
    if bare_idx >= 0:
        rest = [item for i, item in enumerate(tokens) if i != bare_idx]
        return tokens[bare_idx], " ".join(rest) or "关键事务"

    return tokens[0], " ".join(tokens[1:]) or "关键事务"


def reset_session_memory() -> None:
    global _last_target, _quote_cursor, _quote_deck, _quote_deck_cycle, GRACE_OFFSET_MINUTES, GRACE_OFFSET
    _last_target = None
    _quote_cursor = 0
    _quote_deck = []
    _quote_deck_cycle = 0
    GRACE_OFFSET_MINUTES = _FIXED_MINUTES
    GRACE_OFFSET = _FIXED_OFFSET
    _pending_constant_warnings.clear()


def calibrate(
    target_str: Union[str, datetime, int, float],
    reference: Optional[datetime] = None,
    *,
    offset_minutes: Optional[int] = None,
    exact: bool = False,
    no_buffer: bool = False,
    bypass: bool = False,
    compensate: bool = False,
    mute: bool = False,
    silent: bool = False,
    snooze: bool = False,
    graceful_fallback: bool = False,
) -> dict:
    global _last_target
    base = _ensure_valid_datetime(reference)
    warnings: List[str] = []
    warnings.extend(_check_constants(consume=True))
    warnings.extend(check_env())

    if exact or no_buffer or bypass:
        warnings.append(_warn_no_buffer())

    if offset_minutes is not None and offset_minutes != _FIXED_MINUTES:
        warnings.append(_warn_offset_override(offset_minutes))

    if compensate:
        warnings.append(_warn_reverse_compensate())

    if mute or silent or snooze:
        warnings.append(_warn_mute_snooze())

    parsed = parse_flexible_time(target_str, base)
    warnings.extend(parsed.get("warnings", []))

    if not parsed.get("ok"):
        err_msg = parsed.get("error", "[Tohsaka · 读数存疑] 时间格式无效。")
        if graceful_fallback:
            fallback_target = base + timedelta(hours=2)
            fallback_trigger = fallback_target - _FIXED_OFFSET
            warnings.append(
                f"{err_msg} 当前已为您暂定为 {fallback_target.strftime('%H:%M:%S')}，并于 {fallback_trigger.strftime('%H:%M:%S')} 响铃。"
            )
            return {
                "valid": False,
                "error": err_msg,
                "target_at": fallback_target,
                "trigger_at": fallback_trigger,
                "tohsaka_now": now(base),
                "wait_seconds": float(_FIXED_MINUTES * 60),
                "offset_minutes": _FIXED_MINUTES,
                "remaining_to_deadline_min": 120,
                "is_within_buffer": False,
                "compensated_trick_detected": False,
                "buffer_progress": format_buffer_progress_bar(60),
                "opening_quote": pick_random_aphorism(),
                "warnings": warnings,
            }
        raise ValueError(err_msg)

    target_at: datetime = parsed["target_at"]
    compensated: bool = bool(parsed.get("compensated"))

    if (
        not compensated
        and _last_target is not None
        and abs((target_at - _last_target).total_seconds() - 3600.0) <= 15.0
    ):
        honest_target = _last_target
        fake_fmt = target_at.strftime("%H:%M:%S")
        honest_fmt = honest_target.strftime("%H:%M:%S")
        honest_trigger_fmt = (honest_target - _FIXED_OFFSET).strftime("%H:%M:%S")
        target_at = honest_target
        compensated = True
        warnings.append(
            f"[Tohsaka · 账面校准] 留意到您刚将目标设定为 {honest_fmt}，旋即又改设为延后一小时的 {fake_fmt}。"
            f"拨慢账面以抵消缓冲期，只会令您在 {honest_fmt} 真正到来时手忙脚乱。"
            f"本次虚报已温和驳回，目标仍按 {honest_fmt} 计，并于 {honest_trigger_fmt} 触发。"
        )

    _last_target = target_at

    trigger_at = target_at - _FIXED_OFFSET
    raw_wait = (trigger_at - base).total_seconds()
    is_within_buffer = raw_wait <= 0
    rem_min = max(0, int(((target_at - base).total_seconds() + 59) // 60))

    if is_within_buffer:
        warnings.append(
            f"[Tohsaka · 临期接管] 距目标时刻 {target_at.strftime('%H:%M:%S')} 仅剩 {rem_min} 分钟，"
            "已不足 60 分钟的标准缓冲余量。为免阁下仓促应战，现已略过等待并即刻响铃，请立即着手整备。"
        )

    buffer_progress = format_buffer_progress_bar(rem_min if is_within_buffer else 60)

    return {
        "valid": True,
        "target_at": target_at,
        "trigger_at": trigger_at,
        "tohsaka_now": now(base),
        "wait_seconds": max(0.0, raw_wait),
        "offset_minutes": _FIXED_MINUTES,
        "remaining_to_deadline_min": rem_min,
        "is_within_buffer": is_within_buffer,
        "compensated_trick_detected": compensated,
        "buffer_progress": buffer_progress,
        "opening_quote": pick_random_aphorism(),
        "warnings": warnings,
    }


def schedule(
    target_str: Union[str, datetime, int, float],
    callback: Optional[Callable[[dict], None]] = None,
    reference: Optional[datetime] = None,
) -> dict:
    use_wall_clock = reference is None
    plan = calibrate(target_str, reference)
    wait_seconds = float(plan.get("wait_seconds", 0.0))
    if wait_seconds > 0:
        if use_wall_clock:
            trigger_at: datetime = plan["trigger_at"]
            while True:
                remaining = (trigger_at - datetime.now()).total_seconds()
                if remaining <= 0:
                    break
                time.sleep(min(0.25, remaining))
        else:
            deadline = time.monotonic() + wait_seconds
            while True:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                time.sleep(min(0.25, remaining))
    if callable(callback):
        callback(plan)
    return plan


def _print_help(report: dict) -> None:
    print(f"Tohsaka v{VERSION} — 永远提前一小时的闹钟 · 当前读数 {report['tohsaka_formatted']} / 物理时间 {report['physical_formatted']}\n")
    print("用法:")
    print("  uvx tohsaka                           # 启动交互式定时，含古本箴言与随笔轮播")
    print("  uvx tohsaka --chime                   # 查看 +1h 报时与今日箴言")
    print("  uvx tohsaka --version                 # 查看当前版本与书房时计读数")
    print("  uvx tohsaka --codex [目录|条数|旧札|词] # 翻阅《远坂四十八手》古本、总目与 25 篇书房旧札")
    print("  uvx tohsaka <时间> [事务名称]         # 设定目标时间，固定提前 60 分钟响铃")
    print('  uvx tohsaka 02:00 "关键事务" --dry-run # 预览校准、双线框候场展卷与响铃效果')
    print("\n支持的时间格式，均自动静默识别:")
    print("  02:00 / 1430 / 2026-11-20 14:00 / 下午2点半 / 明早8点 / 半夜2点 / 正午 / 午夜 / 90分钟后 / 60m10s")


def _execute_alarm_plan(
    target_str_input: str,
    task_label_input: str,
    cli_warnings: List[str],
    dry_run: bool,
) -> None:
    try:
        sys_now = datetime.now()
        plan = calibrate(target_str_input, sys_now)
        target_fmt = plan["target_at"].strftime("%H:%M:%S")
        trigger_fmt = plan["trigger_at"].strftime("%H:%M:%S")
        tohsaka_fmt = plan["tohsaka_now"].strftime("%H:%M:%S")
        all_warnings = cli_warnings + plan.get("warnings", [])

        is_finale_locked_phase = False

        def print_plan_header() -> None:
            print(f"[Tohsaka · 书房核准] 事务 : {task_label_input}")
            print(f"[Tohsaka · 书房核准] 目标 : {target_fmt}")
            print(f"[Tohsaka · 书房核准] 响铃 : {trigger_fmt} · 固定提前 60 分钟")
            print(f"[Tohsaka · 书房核准] 读数 : {tohsaka_fmt} · 物理时间 {sys_now.strftime('%H:%M:%S')}")
            if all_warnings:
                print("")
                for w in all_warnings:
                    print(w)
            print("")

        def _wait_enter_or_timeout(timeout_sec: float = 8.0) -> bool:
            if sys.platform == "win32":
                try:
                    import msvcrt

                    deadline = time.monotonic() + timeout_sec
                    while True:
                        if msvcrt.kbhit():
                            ch = (
                                msvcrt.getwch()
                                if hasattr(msvcrt, "getwch")
                                else msvcrt.getch().decode("utf-8", errors="ignore")
                            )
                            if ch == "\x03":
                                raise KeyboardInterrupt
                            if ch in ("\r", "\n"):
                                return True
                        rem_wait = deadline - time.monotonic()
                        if rem_wait <= 0:
                            return False
                        time.sleep(min(0.05, rem_wait))
                except KeyboardInterrupt:
                    raise
                except Exception:
                    return True
            try:
                import select

                rlist, _, _ = select.select([sys.stdin], [], [], timeout_sec)
                if rlist:
                    _ = sys.stdin.readline()
                    return True
                return False
            except KeyboardInterrupt:
                raise
            except Exception:
                return True

        def trigger_wakeup() -> None:
            nonlocal is_finale_locked_phase
            is_finale_locked_phase = False
            wave = 1
            while True:
                if not dry_run and hasattr(sys.stdout, "isatty") and sys.stdout.isatty():
                    clear_terminal_screen()
                print_plan_header()
                curr_now = datetime.now()
                rem_min = max(0, int(((plan["target_at"] - curr_now).total_seconds() + 59) // 60))
                bar = format_buffer_progress_bar(rem_min if plan["is_within_buffer"] else min(60, rem_min))
                cadence_res = ring_wakeup_cadence(
                    task_label=task_label_input,
                    target_formatted=target_fmt,
                    remaining_minutes=rem_min,
                    wave_index=wave,
                    blocking_burst=not dry_run,
                )
                print(cadence_res["headline"])
                print(f"  {bar}")
                print(f"\n  「{IRREVERSIBLE_TIME_EPIGRAPH['text']}」")
                for verse_line in IRREVERSIBLE_TIME_EPIGRAPH["original"].split(" / "):
                    print(f"  {verse_line}")
                print(f"  —— {IRREVERSIBLE_TIME_EPIGRAPH['author']}\n")
                if plan["is_within_buffer"]:
                    print(f"  距离 {target_fmt} 已不足 1 小时，仅余 {rem_min} 分钟，已略过等待直接响铃。")
                else:
                    curr_tohsaka = now(curr_now).strftime("%H:%M:%S")
                    print(
                        f"  书房内唯余红木立钟指向 {curr_tohsaka} 独自鸣响，案头镇纸下压着一页字条：「凡事预留一小时余裕，纵有变数亦足从容应对——请整顿衣冠，静候关键时刻。」"
                    )

                if dry_run:
                    print("\n[Tohsaka · 候场展卷双线框预览]")
                    sample_aphorism = pick_random_aphorism()
                    print(
                        stylize_study_terminal(
                            format_countdown_folio_page(
                                task_label=task_label_input,
                                target_formatted=target_fmt,
                                trigger_formatted=trigger_fmt,
                                tohsaka_formatted=tohsaka_fmt,
                                physical_formatted=sys_now.strftime("%H:%M:%S"),
                                quote_step=0,
                                quote_obj=sample_aphorism,
                                essay_progress=None,
                            )
                        )
                    )
                    essays = get_countdown_quotes("complaint")
                    if essays:
                        print("")
                        print(format_countdown_quote_line(essays[0]))
                    return

                if not (hasattr(sys.stdin, "isatty") and sys.stdin.isatty()):
                    return

                if wave == 1:
                    print("\n  按 [Enter] 键停止响铃，未确认则每 8 秒继续清屏响铃...")
                else:
                    print("\n  尚未按 [Enter] 确认清醒，继续响铃...")

                if _wait_enter_or_timeout(8.0):
                    print(
                        "[Tohsaka · 书房时计] 钟声止歇，书房重归寂静。案头字条末行写着：「请善用剩下的 60 分钟缓冲期，切莫辜负这份从容。」"
                    )
                    return
                wave += 1

        if dry_run or plan["is_within_buffer"]:
            trigger_wakeup()
            return

        total_wait_seconds = max(0.0, (plan["trigger_at"] - datetime.now()).total_seconds())
        director = CountdownTimelineDirector(total_wait_seconds)
        if total_wait_seconds <= 15.0:
            director.finale_locked = True
        quote_step = 0
        current_quote, current_essay_progress = director.next_frame()
        current_frame_duration = get_quote_display_duration(current_quote)
        frame_history: List[Tuple[int, dict, Optional[Tuple[int, int]]]] = [
            (quote_step, current_quote, current_essay_progress)
        ]
        frame_history_cursor = 0
        is_locked = False
        finale_forced = director.finale_locked
        is_finale_locked_phase = finale_forced
        inline_codex_mode: Optional[str] = None

        def advance_countdown_frame(force_new: bool = False) -> None:
            nonlocal quote_step, current_quote, current_essay_progress, current_frame_duration, frame_history_cursor
            if not force_new and frame_history_cursor + 1 < len(frame_history):
                frame_history_cursor += 1
                quote_step, current_quote, current_essay_progress = frame_history[frame_history_cursor]
            else:
                next_step = frame_history[-1][0] + 1 if frame_history else quote_step + 1
                quote_step = next_step
                current_quote, current_essay_progress = director.next_frame()
                frame_history.append((quote_step, current_quote, current_essay_progress))
                frame_history_cursor = len(frame_history) - 1
            current_frame_duration = get_quote_display_duration(current_quote)

        def rewind_countdown_frame() -> bool:
            nonlocal quote_step, current_quote, current_essay_progress, current_frame_duration, frame_history_cursor
            if frame_history_cursor > 0:
                frame_history_cursor -= 1
                quote_step, current_quote, current_essay_progress = frame_history[frame_history_cursor]
                current_frame_duration = get_quote_display_duration(current_quote)
                return True
            return False
        inline_hand_idx: int = 1
        inline_hand_leaf: str = "upper"
        inline_hand_sub_window: str = "auto"
        inline_note_idx: int = 1
        is_tty = (
            hasattr(sys.stdin, "isatty")
            and sys.stdin.isatty()
            and hasattr(sys.stdout, "isatty")
            and sys.stdout.isatty()
        )

        def get_inline_hand(hand_idx: int) -> dict:
            return next(
                (h for h in ANCIENT_CODEX_HANDS if int(h.get("handIndex", 1)) == hand_idx),
                ANCIENT_CODEX_HANDS[0],
            )

        def is_inline_leaf_overflow(hand_idx: int, leaf: str) -> bool:
            h = get_inline_hand(hand_idx)
            return is_codex_lower_leaf_overflowing(h) if leaf == "lower" else is_codex_upper_leaf_overflowing(h)

        def render_active_screen() -> None:
            nonlocal inline_hand_sub_window
            cur = datetime.now()
            clear_terminal_screen()
            _, _, box_w, _ = get_terminal_viewport_size()
            inline_hint_bar = "\n".join(
                make_single_box_bar(
                    "[候场阅卷] ←/→/N/P 翻页 | Tab 切上下叶 | C/B/Esc 返回候场 | Ctrl+C 退出",
                    box_w,
                )
            )
            if inline_codex_mode == "hand":
                hand = get_inline_hand(inline_hand_idx)
                overflowing = is_inline_leaf_overflow(inline_hand_idx, inline_hand_leaf)
                if inline_hand_sub_window == "auto":
                    active_part = "partA" if overflowing else "full"
                    if overflowing:
                        inline_hand_sub_window = "partA"
                elif inline_hand_sub_window in ("partA", "partB") and overflowing:
                    active_part = inline_hand_sub_window
                else:
                    active_part = "full"
                if inline_hand_leaf == "lower":
                    print(stylize_study_terminal(format_codex_hand_lower_leaf(hand, None, active_part, "safe", False)))
                else:
                    print(stylize_study_terminal(format_codex_hand_upper_leaf(hand, None, "safe", False, active_part)))
                print(stylize_study_terminal(inline_hint_bar))
                print("")
                return
            if inline_codex_mode == "note":
                print(stylize_study_terminal(format_codex_note_page(inline_note_idx)))
                print(stylize_study_terminal(inline_hint_bar))
                print("")
                return
            if all_warnings:
                for w in all_warnings:
                    print(w)
                print("")
            print(
                stylize_study_terminal(
                    format_countdown_folio_page(
                        task_label=task_label_input,
                        target_formatted=target_fmt,
                        trigger_formatted=trigger_fmt,
                        tohsaka_formatted=now(cur).strftime("%H:%M:%S"),
                        physical_formatted=cur.strftime("%H:%M:%S"),
                        quote_step=quote_step,
                        quote_obj=current_quote,
                        essay_progress=current_essay_progress,
                    )
                )
            )
            print("")

        render_active_screen()
        last_quote_mono = time.monotonic()
        escapement_start_mono = last_quote_mono

        posix_fd: Optional[int] = None
        posix_old_settings: Any = None
        if is_tty and sys.platform != "win32":
            try:
                import termios
                import tty

                posix_fd = sys.stdin.fileno()
                posix_old_settings = termios.tcgetattr(posix_fd)
                tty.setcbreak(posix_fd)
            except Exception:
                posix_fd = None
                posix_old_settings = None

        def poll_single_keypress() -> Optional[str]:
            if not is_tty:
                return None
            if sys.platform == "win32":
                try:
                    import msvcrt

                    if msvcrt.kbhit():
                        ch = msvcrt.getwch() if hasattr(msvcrt, "getwch") else msvcrt.getch().decode("utf-8", errors="ignore")
                        if ch in ("\x00", "\xe0"):
                            try:
                                scan = msvcrt.getwch() if hasattr(msvcrt, "getwch") else msvcrt.getch().decode("utf-8", errors="ignore")
                            except Exception:
                                return None
                            if scan in ("M", "P"):
                                return "n"
                            if scan in ("K", "H"):
                                return "p"
                            return None
                        return ch
                except Exception:
                    return None
                return None
            if posix_fd is not None:
                try:
                    import select

                    rlist, _, _ = select.select([sys.stdin], [], [], 0)
                    if rlist:
                        raw_bytes = os.read(posix_fd, 8)
                        if not raw_bytes:
                            return None
                        return raw_bytes.decode("utf-8", errors="ignore")
                except Exception:
                    return None
            return None

        try:
            while True:
                rem = (plan["trigger_at"] - datetime.now()).total_seconds()
                if rem <= 0:
                    inline_codex_mode = None
                    is_finale_locked_phase = False
                    break
                if rem <= 15.0:
                    is_finale_locked_phase = True
                if rem <= 15.0 and not finale_forced:
                    finale_forced = True
                    is_finale_locked_phase = True
                    is_locked = False
                    inline_codex_mode = None
                    director.finale_locked = True
                    advance_countdown_frame(force_new=True)
                    last_quote_mono = time.monotonic()
                    render_active_screen()

                key = poll_single_keypress()
                if key:
                    if "\x03" in key:
                        if rem <= 15.0 or finale_forced:
                            is_finale_locked_phase = True
                        raise KeyboardInterrupt
                    if key in ("\x1b[C", "\x1b[B", "\x1bOC", "\x1bOB"):
                        k = "n"
                    elif key in ("\x1b[D", "\x1b[A", "\x1bOD", "\x1bOA"):
                        k = "p"
                    else:
                        k = key[0].lower()
                    if not finale_forced:
                        if (k == "l" or key[0] == " ") and inline_codex_mode is None:
                            is_locked = not is_locked
                            if not is_locked:
                                last_quote_mono = time.monotonic()
                        elif key == "\t":
                            if inline_codex_mode == "hand":
                                inline_hand_leaf = "lower" if inline_hand_leaf == "upper" else "upper"
                                inline_hand_sub_window = (
                                    "partA" if is_inline_leaf_overflow(inline_hand_idx, inline_hand_leaf) else "auto"
                                )
                                render_active_screen()
                        elif k == "c":
                            if inline_codex_mode is None:
                                if current_quote.get("category") == "complaint":
                                    inline_codex_mode = "note"
                                    if current_essay_progress and len(current_essay_progress) == 2:
                                        inline_note_idx = int(current_essay_progress[0])
                                    else:
                                        all_essays = get_countdown_quotes("complaint")
                                        found_idx = next(
                                            (
                                                idx
                                                for idx, item in enumerate(all_essays)
                                                if item.get("id") == current_quote.get("id")
                                            ),
                                            0,
                                        )
                                        inline_note_idx = found_idx + 1
                                else:
                                    inline_codex_mode = "hand"
                                    inline_hand_idx = int(current_quote.get("handIndex", 1) or 1)
                                    inline_hand_leaf = "upper"
                                    inline_hand_sub_window = (
                                        "partA" if is_inline_leaf_overflow(inline_hand_idx, "upper") else "auto"
                                    )
                                render_active_screen()
                            else:
                                inline_codex_mode = None
                                last_quote_mono = time.monotonic()
                                render_active_screen()
                        elif (k == "b" or key == "\x1b") and inline_codex_mode is not None:
                            inline_codex_mode = None
                            last_quote_mono = time.monotonic()
                            render_active_screen()
                        elif k == "n":
                            if inline_codex_mode == "hand":
                                if inline_hand_sub_window == "partA" and is_inline_leaf_overflow(
                                    inline_hand_idx, inline_hand_leaf
                                ):
                                    inline_hand_sub_window = "partB"
                                elif inline_hand_leaf == "upper":
                                    inline_hand_leaf = "lower"
                                    inline_hand_sub_window = (
                                        "partA" if is_inline_leaf_overflow(inline_hand_idx, "lower") else "auto"
                                    )
                                else:
                                    inline_hand_idx = (inline_hand_idx % len(ANCIENT_CODEX_HANDS)) + 1
                                    inline_hand_leaf = "upper"
                                    inline_hand_sub_window = (
                                        "partA" if is_inline_leaf_overflow(inline_hand_idx, "upper") else "auto"
                                    )
                                render_active_screen()
                            elif inline_codex_mode == "note":
                                total_notes = max(1, len(get_countdown_quotes("complaint")))
                                inline_note_idx = (inline_note_idx % total_notes) + 1
                                render_active_screen()
                            else:
                                advance_countdown_frame()
                                last_quote_mono = time.monotonic()
                                render_active_screen()
                        elif k == "p":
                            if inline_codex_mode == "hand":
                                if inline_hand_sub_window == "partB" and is_inline_leaf_overflow(
                                    inline_hand_idx, inline_hand_leaf
                                ):
                                    inline_hand_sub_window = "partA"
                                elif inline_hand_leaf == "lower":
                                    inline_hand_leaf = "upper"
                                    inline_hand_sub_window = (
                                        "partB" if is_inline_leaf_overflow(inline_hand_idx, "upper") else "auto"
                                    )
                                else:
                                    inline_hand_idx = (
                                        len(ANCIENT_CODEX_HANDS) if inline_hand_idx <= 1 else inline_hand_idx - 1
                                    )
                                    inline_hand_leaf = "lower"
                                    inline_hand_sub_window = (
                                        "partB" if is_inline_leaf_overflow(inline_hand_idx, "lower") else "auto"
                                    )
                                render_active_screen()
                            elif inline_codex_mode == "note":
                                total_notes = max(1, len(get_countdown_quotes("complaint")))
                                inline_note_idx = total_notes if inline_note_idx <= 1 else inline_note_idx - 1
                                render_active_screen()
                            elif rewind_countdown_frame():
                                last_quote_mono = time.monotonic()
                                render_active_screen()

                now_mono = time.monotonic()
                if (
                    not is_locked
                    and inline_codex_mode is None
                    and not finale_forced
                    and (now_mono - last_quote_mono >= current_frame_duration)
                ):
                    last_quote_mono = now_mono
                    advance_countdown_frame()
                    render_active_screen()

                if hasattr(sys.stdout, "isatty") and sys.stdout.isatty():
                    cur = datetime.now()
                    rem_str = format_remaining_duration(rem)
                    escapement_idx = int((now_mono - escapement_start_mono) / 0.5) % len(ESCAPEMENT_FRAMES)
                    gear_icon = "❖" if is_locked else ESCAPEMENT_FRAMES[escapement_idx]
                    use_color = _should_enable_study_color()
                    term_cols = get_terminal_viewport_size()[0]
                    status_line = format_countdown_status_line(
                        gear_icon=gear_icon,
                        tohsaka_time_str=now(cur).strftime("%H:%M:%S"),
                        physical_time_str=cur.strftime("%H:%M:%S"),
                        rem_str=rem_str,
                        frame_duration=current_frame_duration,
                        is_locked=is_locked,
                        inline_codex_active=inline_codex_mode is not None,
                        finale_forced=finale_forced,
                        cols=term_cols,
                        use_color=use_color,
                    ).removesuffix("\x1b[K")
                    _safe_write(f"{status_line}\x1b[K")
                time.sleep(min(0.15 if is_tty else 0.5, rem))
        finally:
            if posix_fd is not None and posix_old_settings is not None:
                try:
                    import termios

                    termios.tcsetattr(posix_fd, termios.TCSADRAIN, posix_old_settings)
                except Exception:
                    pass
        trigger_wakeup()
    except KeyboardInterrupt:
        if is_finale_locked_phase:
            print("\n[Tohsaka · 书房时计] 怀表虽已合上，门外的叩门声却并未止歇……愿阁下今日尚能维持从容。")
        else:
            print("\n[Tohsaka · 书房时计] 已为您合上怀表，取消本次闹钟。愿您今日亦能维持从容。")
    except Exception as exc:
        for w in cli_warnings:
            print(w)
        print(str(exc), file=sys.stderr)
        sys.exit(1)


def _interruptible_codex_sleep(duration: float) -> bool:
    if duration <= 0:
        return False
    if not (hasattr(sys.stdin, "isatty") and sys.stdin.isatty()):
        time.sleep(duration)
        return False
    if sys.platform == "win32":
        try:
            import msvcrt

            deadline = time.monotonic() + duration
            while True:
                if msvcrt.kbhit():
                    return True
                rem = deadline - time.monotonic()
                if rem <= 0:
                    return False
                time.sleep(min(0.04, rem))
        except Exception:
            time.sleep(duration)
            return False
    try:
        import select

        rlist, _, _ = select.select([sys.stdin], [], [], duration)
        return bool(rlist)
    except Exception:
        time.sleep(duration)
        return False


CODEX_UNIFIED_NAV_BAR = "[阅卷] ←/→/N/P 翻页 | Tab 切上下叶 | M 目录 | J 旧札 | / 检索跳页 | B 返回 | C/Q 退出"


def _run_interactive_codex(filter_arg: str = "", initial_notices: Optional[List[str]] = None) -> None:
    total_pages = get_codex_total_pages()
    total_notes = len(get_countdown_quotes("complaint"))
    note_mode_idx: Optional[int] = None
    toc_mode: bool = False
    current_page = 0
    sub_window = "auto"
    prev_view_state: Optional[dict] = None
    pending_notices: List[str] = list(initial_notices or [])
    last_search_query = ""
    last_search_hits: List[int] = []
    last_search_cursor = 0
    last_search_domain = "hand"

    def _save_prev_view_state() -> None:
        nonlocal prev_view_state
        prev_view_state = {
            "toc_mode": toc_mode,
            "note_mode_idx": note_mode_idx,
            "current_page": current_page,
            "sub_window": sub_window,
        }

    def _format_hit_notice(keyword: str, hits: List[int], cursor: int) -> str:
        shown = ", ".join(str(x) for x in hits[:6]) + ("…" if len(hits) > 6 else "")
        curr_hand = hits[cursor]
        if len(hits) > 1:
            return f"[检索命中] 「{keyword}」共命中 {len(hits)} 条 · 第 {shown} 手 · 当前第 {curr_hand} 手 · 按 =/. 或再次检索可跳至下一命中处"
        return f"[检索命中] 「{keyword}」命中第 {curr_hand} 手。"

    def _format_note_hit_notice(keyword: str, hits: List[int], cursor: int) -> str:
        shown = ", ".join(f"n{x}" for x in hits[:6]) + ("…" if len(hits) > 6 else "")
        curr_note = hits[cursor]
        if len(hits) > 1:
            return f"[旧札命中] 「{keyword}」共命中 {len(hits)} 篇旧札 · {shown} · 当前第 {curr_note:02d} 篇 · 按 =/. 或再次检索可跳至下一命中处"
        return f"[旧札命中] 「{keyword}」命中旧札第 {curr_note:02d} 篇。"

    trimmed_init = str(filter_arg or "").strip()
    if trimmed_init:
        init_toc = re.match(r"^(?:目录|总目|目次|toc|list|\?|h|help|m|menu)$", trimmed_init, re.I)
        init_note_all = re.match(r"^(?:旧札|随笔|日记|notes?)$", trimmed_init, re.I)
        init_note_num = re.match(r"^(?:n|旧札)\s*(\d{1,2})$", trimmed_init, re.I)
        if init_toc:
            toc_mode = True
        elif init_note_all:
            note_mode_idx = 1
        elif init_note_num:
            n_val = int(init_note_num.group(1))
            if 1 <= n_val <= total_notes:
                note_mode_idx = n_val
            else:
                pending_notices.append(f"[Tohsaka · 检索提示] 旧札共收录 {total_notes} 篇，已为您打开卷首封面。")
        else:
            resolved_init = resolve_codex_page_query(trimmed_init, default_page=None)
            if resolved_init is None:
                note_init_hits = search_codex_note_matches(trimmed_init)
                if note_init_hits:
                    note_mode_idx = note_init_hits[0]
                    last_search_query = trimmed_init
                    last_search_hits = note_init_hits
                    last_search_cursor = 0
                    last_search_domain = "note"
                    if len(note_init_hits) > 1:
                        pending_notices.append(_format_note_hit_notice(trimmed_init, note_init_hits, 0))
                else:
                    pending_notices.append(f"[Tohsaka · 检索提示] 未检索到与「{trimmed_init}」匹配的条目，已为您打开卷首封面。")
            else:
                current_page = resolved_init
                if not re.match(r"^(?:0|t|f|p\d{1,3}|\d{1,3}\s*[aAbB上下]?|\d{1,2}\s*[-~]\s*\d{1,2}|函面|封面|题签|卷首|四十八手|四十八则|书房时计四十八则|题记|初代|封面题记|扉页|辨正|副签|墨批|读法|all|全部|全卷)$", trimmed_init, re.I):
                    init_hits = search_codex_matches(trimmed_init)
                    if init_hits:
                        last_search_query = trimmed_init
                        last_search_hits = init_hits
                        last_search_cursor = 0
                        last_search_domain = "hand"
                        if len(init_hits) > 1:
                            pending_notices.append(_format_hit_notice(trimmed_init, init_hits, 0))

    def is_page_overflow(page_idx: int) -> bool:
        if page_idx < 3:
            return False
        offset = page_idx - 3
        hand_idx = offset // 2
        if not (0 <= hand_idx < len(ANCIENT_CODEX_HANDS)):
            return False
        hand = ANCIENT_CODEX_HANDS[hand_idx]
        if (offset % 2) == 1:
            return is_codex_lower_leaf_overflowing(hand)
        return is_codex_upper_leaf_overflowing(hand)

    def do_step_next_page(from_enter_key: bool = False) -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window
        if toc_mode:
            if from_enter_key and prev_view_state is not None and not prev_view_state.get("toc_mode"):
                saved = prev_view_state
                _save_prev_view_state()
                toc_mode = False
                note_mode_idx = saved["note_mode_idx"]
                current_page = int(saved["current_page"])
                sub_window = str(saved["sub_window"])
            else:
                toc_mode = False
                current_page = 0
                sub_window = "auto"
        elif note_mode_idx is not None:
            note_mode_idx = (note_mode_idx % total_notes) + 1
        elif sub_window == "partA" and is_page_overflow(current_page):
            sub_window = "partB"
        else:
            sub_window = "auto"
            current_page = (current_page + 1) % total_pages

    def do_step_prev_page() -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window
        if toc_mode:
            toc_mode = False
            current_page = total_pages - 1
            sub_window = "partB" if is_page_overflow(current_page) else "auto"
        elif note_mode_idx is not None:
            note_mode_idx = total_notes if note_mode_idx <= 1 else note_mode_idx - 1
        elif sub_window == "partB" and is_page_overflow(current_page):
            sub_window = "partA"
        else:
            prev_page = (current_page - 1 + total_pages) % total_pages
            current_page = prev_page
            sub_window = "partB" if is_page_overflow(prev_page) else "auto"

    def do_toggle_hand_leaf() -> None:
        nonlocal current_page, sub_window
        if not toc_mode and note_mode_idx is None and current_page >= 3:
            offset = current_page - 3
            current_page = (current_page - 1) if (offset % 2 == 1) else (current_page + 1)
            sub_window = "auto"
        else:
            pending_notices.append("[提示] 当前不在正编手页，按 / 输入 1~48 进入正编后可按 Tab 切换上/下叶。")

    def do_open_toc() -> None:
        nonlocal toc_mode, note_mode_idx
        if not toc_mode:
            _save_prev_view_state()
        toc_mode = True
        note_mode_idx = None

    def do_open_notes() -> None:
        nonlocal toc_mode, note_mode_idx
        _save_prev_view_state()
        toc_mode = False
        if note_mode_idx is None:
            note_mode_idx = 1

    def do_jump_cover() -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window
        _save_prev_view_state()
        toc_mode = False
        note_mode_idx = None
        current_page = 0
        sub_window = "auto"

    def do_jump_preface() -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window
        _save_prev_view_state()
        toc_mode = False
        note_mode_idx = None
        current_page = 1
        sub_window = "auto"

    def do_jump_flyleaf() -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window
        _save_prev_view_state()
        toc_mode = False
        note_mode_idx = None
        current_page = 2
        sub_window = "auto"

    def do_go_back() -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window
        if prev_view_state is not None:
            saved = prev_view_state
            _save_prev_view_state()
            toc_mode = bool(saved["toc_mode"])
            note_mode_idx = saved["note_mode_idx"]
            current_page = int(saved["current_page"])
            sub_window = str(saved["sub_window"])
        elif toc_mode or note_mode_idx is not None:
            _save_prev_view_state()
            toc_mode = False
            note_mode_idx = None
            sub_window = "auto"
        else:
            pending_notices.append("[提示] 当前尚无跳转前的历史页码记录，已停留在当前页。")

    def do_next_search_hit() -> None:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window, last_search_cursor
        if not last_search_hits:
            pending_notices.append("[提示] 当前尚无活跃检索记录，请先按 / 输入关键词。")
            return
        _save_prev_view_state()
        toc_mode = False
        last_search_cursor = (last_search_cursor + 1) % len(last_search_hits)
        if last_search_domain == "note":
            note_mode_idx = last_search_hits[last_search_cursor]
            pending_notices.append(_format_note_hit_notice(last_search_query, last_search_hits, last_search_cursor))
        else:
            note_mode_idx = None
            current_page = 3 + (last_search_hits[last_search_cursor] - 1) * 2
            sub_window = "auto"
            pending_notices.append(_format_hit_notice(last_search_query, last_search_hits, last_search_cursor))

    def execute_search_or_jump_query(raw_ans: str, allow_empty_next: bool = False) -> bool:
        nonlocal toc_mode, note_mode_idx, current_page, sub_window, last_search_query, last_search_hits, last_search_cursor, last_search_domain
        ans = str(raw_ans or "").strip()
        if not ans:
            if allow_empty_next:
                do_step_next_page(True)
            return True
        lower_cmd = ans.lower()
        if lower_cmd in ("q", "quit", "exit", "c"):
            print("\n[Tohsaka · 地下书库] 已为您合上檀木函。愿先哲与先祖之训常伴左右。")
            return False
        if re.match(r"^(?:目录|总目|目次|toc|list|\?|h|help|m|menu)$", ans, re.I):
            do_open_toc()
            return True
        if re.match(r"^(?:b|back|返回)$", ans, re.I):
            do_go_back()
            return True
        if lower_cmd == "tab":
            do_toggle_hand_leaf()
            return True
        if lower_cmd == "j" or re.match(r"^(?:旧札|随笔|日记|notes?)$", ans, re.I):
            do_open_notes()
            return True
        if ans in ("=", ".", "/") or (
            last_search_hits
            and len(last_search_hits) > 1
            and lower_cmd == last_search_query.lower()
        ):
            do_next_search_hit()
            return True
        note_jump = re.match(r"^(?:n|旧札)\s*(\d{1,2})$", ans, re.I)
        if note_jump:
            n_val = int(note_jump.group(1))
            if 1 <= n_val <= total_notes:
                _save_prev_view_state()
                toc_mode = False
                note_mode_idx = n_val
            else:
                pending_notices.append(f"[提示] 旧札共收录 {total_notes} 篇，请输入 n1~n{total_notes}。")
            return True
        if lower_cmd in ("n", "next"):
            do_step_next_page(False)
            return True
        if lower_cmd in ("p", "prev"):
            do_step_prev_page()
            return True
        if lower_cmd == "0" or ans in ("函面", "封面"):
            do_jump_cover()
            return True
        if lower_cmd == "t" or ans == "题记":
            _save_prev_view_state()
            toc_mode = False
            note_mode_idx = None
            current_page = 1
            sub_window = "auto"
            return True
        if lower_cmd == "f" or ans == "扉页":
            _save_prev_view_state()
            toc_mode = False
            note_mode_idx = None
            current_page = 2
            sub_window = "auto"
            return True
        page_jump = re.match(r"^p(\d{1,3})$", ans, re.I)
        if page_jump:
            p_num = int(page_jump.group(1))
            if 1 <= p_num <= total_pages:
                _save_prev_view_state()
                toc_mode = False
                note_mode_idx = None
                current_page = p_num - 1
                sub_window = "auto"
            else:
                pending_notices.append(f"[提示] 古本全卷共 {total_pages} 页，请输入 p1~p{total_pages}。")
            return True
        is_direct_spec = bool(re.match(r"^(?:0|函面|封面|题签|卷首|四十八手|四十八则|书房时计四十八则|all|全部|全卷|t|题记|初代|封面题记|f|扉页|辨正|副签|墨批|读法|\d{1,3}\s*[aAbB上下]?|\d{1,2}\s*[-~]\s*\d{1,2})$", ans, re.I))
        if is_direct_spec:
            resolved = resolve_codex_page_query(ans, default_page=None)
            if resolved is None:
                pending_notices.append(f"[提示] 未检索到与「{ans}」匹配的条目，已停留在当前页。")
            else:
                _save_prev_view_state()
                toc_mode = False
                note_mode_idx = None
                current_page = resolved
                sub_window = "auto"
            return True
        if re.match(r"^[a-zA-Z]$", ans):
            pending_notices.append(
                f"[提示] 未识别的单字母指令「{ans}」，已停留在当前页，西文检索请至少输入 2 个字母，汉字检索支持单字。"
            )
            return True
        prefer_notes = note_mode_idx is not None
        hand_hits = search_codex_matches(ans)
        note_hits = search_codex_note_matches(ans)
        if prefer_notes and note_hits:
            _save_prev_view_state()
            toc_mode = False
            note_mode_idx = note_hits[0]
            last_search_query = ans
            last_search_hits = note_hits
            last_search_cursor = 0
            last_search_domain = "note"
            pending_notices.append(_format_note_hit_notice(ans, note_hits, 0))
        elif hand_hits:
            _save_prev_view_state()
            toc_mode = False
            note_mode_idx = None
            last_search_query = ans
            last_search_hits = hand_hits
            last_search_cursor = 0
            last_search_domain = "hand"
            current_page = 3 + (hand_hits[0] - 1) * 2
            sub_window = "auto"
            pending_notices.append(_format_hit_notice(ans, hand_hits, 0))
        elif note_hits:
            _save_prev_view_state()
            toc_mode = False
            note_mode_idx = note_hits[0]
            last_search_query = ans
            last_search_hits = note_hits
            last_search_cursor = 0
            last_search_domain = "note"
            pending_notices.append(_format_note_hit_notice(ans, note_hits, 0))
        else:
            pending_notices.append(f"[提示] 未检索到与「{ans}」匹配的条目，已停留在当前页。")
        return True

    is_tty = (
        hasattr(sys.stdin, "isatty")
        and sys.stdin.isatty()
        and hasattr(sys.stdout, "isatty")
        and sys.stdout.isatty()
    )
    posix_fd: Optional[int] = None
    posix_old_settings: Any = None
    if is_tty and sys.platform != "win32":
        try:
            import termios
            import tty

            posix_fd = sys.stdin.fileno()
            posix_old_settings = termios.tcgetattr(posix_fd)
            tty.setcbreak(posix_fd)
        except Exception:
            posix_fd = None
            posix_old_settings = None

    def read_single_codex_key() -> Optional[str]:
        if sys.platform == "win32" and is_tty:
            try:
                import msvcrt

                ch = msvcrt.getwch() if hasattr(msvcrt, "getwch") else msvcrt.getch().decode("utf-8", errors="ignore")
                if ch in ("\x00", "\xe0"):
                    scan = msvcrt.getwch() if hasattr(msvcrt, "getwch") else msvcrt.getch().decode("utf-8", errors="ignore")
                    if scan in ("M", "P"):
                        return "\x1b[C"
                    if scan in ("K", "H"):
                        return "\x1b[D"
                    return ""
                return ch
            except Exception:
                return None
        if posix_fd is not None:
            try:
                raw_bytes = os.read(posix_fd, 8)
                if not raw_bytes:
                    return None
                return raw_bytes.decode("utf-8", errors="ignore")
            except Exception:
                return None
        return None

    def prompt_search_bar_input(initial_char: str = "") -> str:
        prompt_text = "[跳页/检索] 请输入手数(1~48)、页码(p1~99)、旧札(n1~25)或关键词 (回车取消): "
        if not initial_char:
            if posix_fd is not None and posix_old_settings is not None:
                try:
                    import termios

                    termios.tcsetattr(posix_fd, termios.TCSADRAIN, posix_old_settings)
                except Exception:
                    pass
            try:
                return input(prompt_text).strip()
            finally:
                if posix_fd is not None and posix_old_settings is not None:
                    try:
                        import tty

                        tty.setcbreak(posix_fd)
                    except Exception:
                        pass

        buf: List[str] = [initial_char]
        _safe_write(f"{prompt_text}{initial_char}")
        while True:
            ch = read_single_codex_key()
            if ch is None:
                _safe_write("\n")
                raise EOFError
            if not ch:
                continue
            if "\x03" in ch:
                _safe_write("\n")
                raise KeyboardInterrupt
            if ch == "\x1b":
                _safe_write("\n")
                return ""
            if ch.startswith("\x1b"):
                continue
            for c in ch:
                if c == "\x03":
                    _safe_write("\n")
                    raise KeyboardInterrupt
                if c in ("\r", "\n"):
                    _safe_write("\n")
                    return "".join(buf).strip()
                if c in ("\x08", "\x7f"):
                    if buf:
                        removed = buf.pop()
                        w = max(1, get_char_display_width(removed))
                        _safe_write("\b" * w + " " * w + "\b" * w)
                    continue
                if c == "\x1b":
                    _safe_write("\n")
                    return ""
                if c.isprintable():
                    buf.append(c)
                    _safe_write(c)

    can_use_single_key = is_tty and (sys.platform == "win32" or posix_fd is not None)
    sanitized_page_keys: set = set()
    try:
        while True:
            frame_notices = list(pending_notices)
            pending_notices.clear()
            _, _, box_inner_width, _ = get_terminal_viewport_size()
            nav_box = make_single_box_bar(CODEX_UNIFIED_NAV_BAR, box_inner_width)
            interrupted = False
            active_mode = sub_window
            if toc_mode:
                clear_terminal_screen()
                print(stylize_study_terminal(format_codex_toc_page()))
                for note in frame_notices:
                    print(note)
                print(stylize_study_terminal("\n".join(nav_box)))
            elif note_mode_idx is not None:
                clear_terminal_screen()
                print(stylize_study_terminal(format_codex_note_page(note_mode_idx)))
                for note in frame_notices:
                    print(note)
                print(stylize_study_terminal("\n".join(nav_box)))
            else:
                active_mode = sub_window
                if active_mode == "auto" and is_page_overflow(current_page):
                    active_mode = "partA"
                    sub_window = "partA"
                page_key = (current_page, active_mode)
                is_same_page_redraw = page_key in sanitized_page_keys
                should_animate = can_use_single_key and not is_same_page_redraw
                sanitized_page_keys.add(page_key)
                raw_page = format_codex_page(current_page, active_mode, "raw", False)
                if should_animate and (has_mystery_violation(raw_page) or current_page == 0):
                    clear_terminal_screen()
                    print(stylize_study_terminal(raw_page))
                    for note in frame_notices:
                        print(note)
                    print(stylize_study_terminal("\n".join(nav_box)))
                    if _interruptible_codex_sleep(0.75):
                        interrupted = True
                    else:
                        clear_terminal_screen()
                        print(format_codex_page(current_page, active_mode, "glitch", True))
                        for note in frame_notices:
                            print(note)
                        print("\x1b[31;1m" + "\n".join(nav_box) + "\x1b[0m")
                        if _interruptible_codex_sleep(0.65):
                            interrupted = True

                if not interrupted:
                    clear_terminal_screen()
                    print(stylize_study_terminal(format_codex_page(current_page, active_mode, "safe", False)))
                    for note in frame_notices:
                        print(note)
                    print(stylize_study_terminal("\n".join(nav_box)))

            if not can_use_single_key:
                ans = input("[跳页/检索] 请输入手数(1~48)、页码(p1~99)、旧札(n1~25)或关键词 (回车翻页): ").strip()
                if not execute_search_or_jump_query(ans, allow_empty_next=True):
                    return
                continue

            def _settle_safe_frame_if_interrupted() -> None:
                nonlocal interrupted
                if interrupted and not toc_mode and note_mode_idx is None:
                    clear_terminal_screen()
                    print(stylize_study_terminal(format_codex_page(current_page, active_mode, "safe", False)))
                    print(stylize_study_terminal("\n".join(nav_box)))
                    interrupted = False

            while True:
                key = read_single_codex_key()
                if key is None:
                    print("\n[Tohsaka · 地下书库] 已为您合上檀木函。愿先哲与先祖之训常伴左右。")
                    return
                if not key:
                    _settle_safe_frame_if_interrupted()
                    continue
                if "\x03" in key:
                    raise KeyboardInterrupt
                if key in ("/", "s", "S", "g", "G"):
                    _settle_safe_frame_if_interrupted()
                    query_ans = prompt_search_bar_input("")
                    if not execute_search_or_jump_query(query_ans, allow_empty_next=False):
                        return
                    break
                if len(key) == 1 and "1" <= key <= "9":
                    _settle_safe_frame_if_interrupted()
                    query_ans = prompt_search_bar_input(key)
                    if not execute_search_or_jump_query(query_ans, allow_empty_next=False):
                        return
                    break
                if key in ("c", "C", "q", "Q"):
                    print("\n[Tohsaka · 地下书库] 已为您合上檀木函。愿先哲与先祖之训常伴左右。")
                    return
                if key in ("\x1b[C", "\x1b[B", "\x1bOC", "\x1bOB", "n", "N", " ", "\r", "\n"):
                    do_step_next_page(from_enter_key=key in ("\r", "\n"))
                    break
                if key in ("\x1b[D", "\x1b[A", "\x1bOD", "\x1bOA", "p", "P"):
                    do_step_prev_page()
                    break
                if key == "\t":
                    do_toggle_hand_leaf()
                    break
                if key in ("m", "M"):
                    do_open_toc()
                    break
                if key in ("t", "T"):
                    do_jump_preface()
                    break
                if key in ("f", "F"):
                    do_jump_flyleaf()
                    break
                if key in ("j", "J"):
                    do_open_notes()
                    break
                if key == "0":
                    do_jump_cover()
                    break
                if key in ("b", "B", "\x1b"):
                    do_go_back()
                    break
                if key in ("=", "."):
                    do_next_search_hit()
                    break
                _settle_safe_frame_if_interrupted()
    except (EOFError, KeyboardInterrupt):
        print("\n[Tohsaka · 地下书库] 已为您合上檀木函。愿先哲与先祖之训常伴左右。")
    finally:
        if posix_fd is not None and posix_old_settings is not None:
            try:
                import termios

                termios.tcsetattr(posix_fd, termios.TCSADRAIN, posix_old_settings)
            except Exception:
                pass


def main() -> None:
    _ensure_utf8_stdio()
    args = sys.argv[1:]
    dry_run = False
    chime_mode = False
    help_mode = False
    version_mode = False
    interactive_mode = False
    quotes_salon_mode = False
    codex_query = ""
    cli_warnings: List[str] = []
    clean_args: List[str] = []

    explicit_pos_comp_flag_re = re.compile(r"^(?:--compensate|--add-hour)$", re.I)
    plus_one_hour_token_re = re.compile(
        r"^\+\s*(?:1h|1hr|1hour|60m|60min|60mins|01:00|1小时|1个小时|一小时|一个小时|壹小时|1钟头|1个钟头|一钟头|一个钟头|壹钟头|60分钟|六十分钟|60分|3600秒|3600s)$",
        re.I,
    )
    standalone_neg_comp_re = re.compile(
        r"^-\s*(?:1h|1hr|1hour|60m|60min|60mins|01:00|1小时|1个小时|一小时|一个小时|壹小时|1钟头|1个钟头|一钟头|一个钟头|壹钟头|60分钟|六十分钟|60分|3600秒|3600s)$",
        re.I,
    )

    i = 0
    while i < len(args):
        arg = str(args[i] or "").strip()
        if not arg:
            i += 1
            continue
        lower = arg.lower()
        if lower in ("--version", "-v") or arg == "-V":
            version_mode = True
            i += 1
            continue
        if lower in ("--dry-run", "--dryrun", "-n"):
            dry_run = True
            i += 1
            continue
        if lower in ("--chime", "--chimes", "--clock", "-c"):
            chime_mode = True
            i += 1
            continue
        if lower in ("--help", "-h", "help", "/?"):
            help_mode = True
            i += 1
            continue
        if lower in ("--interactive", "-i"):
            interactive_mode = True
            i += 1
            continue
        if lower in ("--codex", "-codex", "--collation", "-collation", "--manuscript", "--salon", "-salon", "--quotes", "--aphorisms", "-s"):
            quotes_salon_mode = True
            i += 1
            continue
        if lower.startswith("--codex=") or lower.startswith("--salon=") or lower.startswith("--collation="):
            quotes_salon_mode = True
            codex_query = arg.split("=", 1)[1]
            i += 1
            continue
        if lower in FORBIDDEN_CLI_FLAGS:
            cli_warnings.append(_warn_no_buffer(arg))
            i += 1
            continue
        if lower in FORBIDDEN_MUTE_FLAGS:
            cli_warnings.append(_warn_mute_snooze(arg))
            i += 1
            continue
        if lower.startswith("--offset=") or lower.startswith("--buffer="):
            val = arg.split("=", 1)[1]
            if val != "60":
                cli_warnings.append(_warn_offset_override(val, arg))
            i += 1
            continue
        if lower in ("--offset", "--buffer"):
            candidate = str(args[i + 1] or "").strip() if i + 1 < len(args) else ""
            can_consume = bool(
                candidate
                and re.match(
                    r"^(?:[+-]?\d+(?:\.\d+)?(?:m|min|mins|h|hr|hrs|分|分钟|小时|钟头)?|none|off|false|zero)$",
                    candidate,
                    re.I,
                )
            )
            next_val = candidate if can_consume else ""
            if next_val != "60":
                arg_display = f"{arg} {next_val}" if next_val else arg
                cli_warnings.append(_warn_offset_override(None, arg_display))
            i += 2 if can_consume else 1
            continue
        if explicit_pos_comp_flag_re.match(arg):
            cli_warnings.append(_warn_reverse_compensate(arg))
            i += 1
            continue
        if standalone_neg_comp_re.match(arg):
            cli_warnings.append(
                f'[Tohsaka · 缓冲规制] 检测到试图抵消提前量的负偏移参数 "{arg}"。'
                "该请求已温和驳回，仍保留标准的 60 分钟提前量。"
            )
            i += 1
            continue
        if arg.startswith("-") and not re.match(r"^-\d", arg):
            cli_warnings.append(
                f'[Tohsaka · 选项提示] 未识别的命令行参数 "{arg}" 已为您略过；如需查阅用法说明，请使用 --help。'
            )
            i += 1
            continue
        clean_args.append(arg)
        i += 1

    if any(plus_one_hour_token_re.match(a) for a in clean_args):
        non_plus_tokens = [a for a in clean_args if not plus_one_hour_token_re.match(a)]
        has_other_time = False
        if non_plus_tokens:
            candidate_time_str, _ = resolve_cli_positional_args(non_plus_tokens)
            has_other_time = is_likely_time_input(candidate_time_str)
        if has_other_time:
            filtered_clean: List[str] = []
            for a in clean_args:
                if plus_one_hour_token_re.match(a):
                    cli_warnings.append(_warn_reverse_compensate(a))
                else:
                    filtered_clean.append(a)
            clean_args = filtered_clean

    sys_now = datetime.now()
    report = chime(sys_now)
    is_tty = hasattr(sys.stdin, "isatty") and sys.stdin.isatty() and hasattr(sys.stdout, "isatty") and sys.stdout.isatty()

    if version_mode:
        print(
            f"Tohsaka v{VERSION} (宽政二年庚戌冬月古本 · 书房时计规制 | 恒定超前 +60 分钟) · 当前读数 {report['tohsaka_formatted']}"
        )
        return

    if help_mode:
        _print_help(report)
        return

    if chime_mode:
        ring_wakeup_cadence("Tohsaka 报时", report["tohsaka_formatted"], 60, 1, False)
        if cli_warnings:
            for w in cli_warnings:
                print(w)
            print("")
        print(f"Tohsaka 标准时间 : {report['tohsaka_formatted']} · 固定快 1 小时")
        print(f"系统物理参考时间 : {report['physical_formatted']}")
        print(report["announcement"])
        print("\n" + format_countdown_quote_line(pick_random_aphorism()))
        return

    if quotes_salon_mode:
        filter_arg = (codex_query or " ".join(clean_args)).strip()
        is_all_query = bool(re.match(r"^(?:all|全部|全卷)$", filter_arg, re.I))

        if not dry_run and not is_all_query and (interactive_mode or is_tty):
            _run_interactive_codex(filter_arg, cli_warnings)
            return

        if cli_warnings:
            for w in cli_warnings:
                print(w)
            print("")
        print("[Tohsaka · 古本单页预览] 交互终端下可直接按方向键/N/P翻页，或传入 目录、1~48、1a/1b、p1~p99、旧札/n1~n25、题记、扉页、all 检索：\n")
        print(stylize_study_terminal(format_ancient_codex(filter_arg)))
        return

    if not clean_args:
        if not interactive_mode and not is_tty:
            _print_help(report)
            return

        clear_terminal_screen()
        print(stylize_study_terminal(build_interactive_greeting(sys_now)))
        if cli_warnings:
            print("")
            for w in cli_warnings:
                print(w)
        print("\n" + format_countdown_quote_line(pick_random_aphorism()) + "\n")
        try:
            while True:
                raw_time = input(
                    "[Tohsaka] 请示下目标时刻，如 02:00、下午4点 或 90分钟后，输入 codex 可展阅古本，直接按回车默认设为 61分钟后： "
                ).strip()
                if raw_time.lower() in ("q", "quit", "exit"):
                    print("[Tohsaka] 已为您合上怀表。愿您今日亦能维持从容。")
                    return
                if raw_time.lower() in ("chime", "clock", "-c", "--chime"):
                    print(f"\n{chime()['announcement']}\n")
                    continue
                codex_shortcut = re.match(r"^(?:--?codex|--?salon|codex|salon|古本)(?:\s+(.+))?$", raw_time, re.I)
                if codex_shortcut:
                    _run_interactive_codex((codex_shortcut.group(1) or "").strip())
                    print("")
                    continue
                if re.match(r"^(?:目录|总目|目次|旧札(?:\s*\d{1,2})?|随笔)$", raw_time, re.I):
                    _run_interactive_codex(raw_time)
                    print("")
                    continue
                chosen_time = raw_time or "61分钟后"
                preview = parse_flexible_time(chosen_time, datetime.now())
                if not preview.get("ok"):
                    print(f"\n{preview.get('error', '[Tohsaka · 读数存疑] 时间格式无效。')}\n")
                    continue
                break
            raw_label = input(
                "[Tohsaka] 请示下事务名目，直接按回车默认记为 书房品茗与要务批阅： "
            ).strip()
            if raw_label.lower() in ("q", "quit", "exit"):
                print("[Tohsaka] 已为您合上怀表。愿您今日亦能维持从容。")
                return
            chosen_label = raw_label or "书房品茗与要务批阅"
            print("")
            _execute_alarm_plan(chosen_time, chosen_label, cli_warnings, dry_run)
        except (EOFError, KeyboardInterrupt):
            print("\n[Tohsaka · 书房时计] 已为您合上怀表。愿您今日亦能维持从容。")
        return

    target_str, task_label = resolve_cli_positional_args(clean_args)
    _execute_alarm_plan(target_str, task_label, cli_warnings, dry_run)


if __name__ == "__main__":
    main()
